type ScopedQuery<T> = {
  eq: (column: string, value: unknown) => T;
  in: (column: string, values: readonly string[]) => T;
  or: (filters: string) => T;
};

function safeString(value: unknown, fallback = "") {
  return typeof value === "string" ? value : fallback;
}

function safeNumber(value: unknown, fallback = 0) {
  if (typeof value === "number") {
    return value;
  }

  if (typeof value === "string" && value.length > 0) {
    const parsed = Number(value);
    return Number.isNaN(parsed) ? fallback : parsed;
  }

  return fallback;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  if (Array.isArray(value)) {
    const [first] = value;
    return first && typeof first === "object" ? (first as Record<string, unknown>) : null;
  }

  if (value && typeof value === "object") {
    return value as Record<string, unknown>;
  }

  return null;
}

function formatCurrency(value: number) {
  return `KES ${new Intl.NumberFormat("en-KE", {
    maximumFractionDigits: 0,
  }).format(value)}`;
}

function toTitle(value: string) {
  return value
    .split(/[_\s-]+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function normaliseLeaveCode(value: string) {
  return value.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_");
}

function findDefaultLeavePolicyDefinition(value: string) {
  const normalized = normaliseLeaveCode(value);
  return DEFAULT_LEAVE_POLICY_DEFINITIONS.find(
    (definition) => definition.code === normalized || normaliseLeaveCode(definition.name) === normalized
  );
}

function toDateOnlyString(value: Date | string) {
  const date = typeof value === "string" ? new Date(`${value}T00:00:00.000Z`) : value;
  return Number.isNaN(date.getTime()) ? "" : date.toISOString().slice(0, 10);
}

function parseDateOnlyUtc(value: string, errorCode = "invalid_date") {
  const normalized = safeString(value);
  const parsed = normalized ? new Date(`${normalized}T00:00:00.000Z`) : null;
  if (!parsed || Number.isNaN(parsed.getTime())) {
    throw new Error(errorCode);
  }
  return parsed;
}

function countOverlappingDaysInclusive(
  leftStart: Date,
  leftEnd: Date,
  rightStart: Date,
  rightEnd: Date
) {
  const overlapStart = leftStart > rightStart ? leftStart : rightStart;
  const overlapEnd = leftEnd < rightEnd ? leftEnd : rightEnd;

  if (overlapEnd < overlapStart) {
    return 0;
  }

  return diffInDaysInclusive(overlapStart, overlapEnd);
}

function parseJsonTextArray(value: unknown) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.map((entry) => safeString(entry)).filter(Boolean);
}

function formatDateLabel(value: string | null | undefined, fallback = "______________") {
  const normalized = safeString(value);
  if (!normalized) {
    return fallback;
  }
  const date = new Date(`${normalized}T00:00:00.000Z`);
  if (Number.isNaN(date.getTime())) {
    return normalized;
  }
  return date.toLocaleString("en-KE", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });
}

function formatDateTimeLabel(value: string | null | undefined) {
  const normalized = safeString(value);
  if (!normalized) {
    return new Date().toLocaleString("en-KE", {
      day: "2-digit",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZone: "Africa/Nairobi",
    });
  }
  const date = new Date(normalized);
  if (Number.isNaN(date.getTime())) {
    return normalized;
  }
  return date.toLocaleString("en-KE", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    timeZone: "Africa/Nairobi",
  });
}

function buildLogoMark(displayName: string, identifier?: string | null) {
  const seed = safeString(identifier) || displayName || "Solva HR";
  const words = seed
    .split(/[\s-]+/)
    .map((part) => part.trim())
    .filter(Boolean);
  const mark = (words.slice(0, 2).map((part) => part.charAt(0)).join("") || seed.slice(0, 2) || "S")
    .toUpperCase();
  return mark.slice(0, 2);
}

async function createSignedStorageUrl(bucket: string, path: string | null | undefined) {
  if (!path) {
    return "";
  }

  const admin = createSupabaseAdminClient();
  const signed = await admin.storage.from(bucket).createSignedUrl(path, 60 * 60 * 24 * 7);
  if (signed.error || !signed.data?.signedUrl) {
    return "";
  }

  return signed.data.signedUrl;
}

async function downloadCompanyLogoBinary(path: string | null | undefined) {
  if (!path || !/\.(png|jpe?g)$/i.test(path)) {
    return null;
  }

  const admin = createSupabaseAdminClient();
  const bucket = getStorageBucketNames().payrollDocuments;
  const download = await admin.storage.from(bucket).download(path);
  if (download.error || !download.data) {
    return null;
  }

  return new Uint8Array(await download.data.arrayBuffer());
}

async function loadPlatformLogoJpeg() {
  return getBundledSolvaHrLogoJpeg();
}

async function getCompanyBrandingContext(
  companyId: string | null | undefined,
  fallbackName = "Solva HR Workspace",
  fallbackIdentifier = ""
) {
  const fallbackAddressLines = ["Nairobi, Kenya"];

  if (!companyId) {
    return {
      organizationName: fallbackName,
      organizationIdentifier: fallbackIdentifier,
      organizationLogoMark: buildLogoMark(fallbackName, fallbackIdentifier),
      organizationLogoJpeg: null,
      platformLogoJpeg: await loadPlatformLogoJpeg(),
      organizationAddressLines: fallbackAddressLines,
      reportFooter: DEFAULT_SOLVA_REPORT_FOOTER,
    };
  }

  const supabase = createSupabaseAdminClient();
  const [companyResult, settingsResult] = await Promise.all([
    supabase.from("companies").select("name, slug").eq("id", companyId).maybeSingle(),
    supabase
      .from("company_settings")
      .select("branding, physical_address, country")
      .eq("company_id", companyId)
      .maybeSingle(),
  ]);

  if (companyResult.error) {
    throw companyResult.error;
  }

  if (settingsResult.error) {
    throw settingsResult.error;
  }

  const company = companyResult.data as Record<string, unknown> | null;
  const branding = asRecord((settingsResult.data as Record<string, unknown> | null)?.branding);
  const settings = settingsResult.data as Record<string, unknown> | null;
  const organizationName = safeString(branding?.displayName, safeString(company?.name, fallbackName));
  const organizationIdentifier = safeString(
    branding?.employerIdentifier,
    safeString(company?.slug, fallbackIdentifier)
  ).toUpperCase();
  const logoPath = safeString(branding?.logoPath);
  const physicalAddress = safeString(settings?.physical_address);
  const country = safeString(settings?.country, "Kenya");
  const organizationAddressLines = physicalAddress
    ? physicalAddress
        .split(",")
        .map((part) => part.trim())
        .filter(Boolean)
    : fallbackAddressLines;
  if (!organizationAddressLines.some((line) => line.toLowerCase().includes(country.toLowerCase()))) {
    organizationAddressLines.push(country);
  }

  return {
    organizationName,
    organizationIdentifier,
    organizationLogoMark: safeString(branding?.logoMark, buildLogoMark(organizationName, organizationIdentifier)),
    organizationLogoJpeg: await downloadCompanyLogoBinary(logoPath),
    platformLogoJpeg: await loadPlatformLogoJpeg(),
    organizationAddressLines,
    reportFooter: safeString(branding?.reportFooter, DEFAULT_SOLVA_REPORT_FOOTER),
  };
}

function addMonthsPreservingDay(value: string, months: number) {
  if (!value) {
    return "";
  }

  const date = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(date.getTime())) {
    return "";
  }

  const next = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + months, date.getUTCDate()));
  next.setUTCDate(next.getUTCDate() - 1);
  return next.toISOString().slice(0, 10);
}

function addDaysIso(value: string, days: number) {
  if (!value) {
    return "";
  }

  const date = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(date.getTime())) {
    return "";
  }

  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function getDefaultHrSignatories() {
  return {
    humanResources: {
      name: "HR Admin",
      title: "HR Admin",
      initials: "HRA",
      label: "Authorized Signatory",
    },
    generalManager: {
      name: "General Manager",
      title: "General Manager",
      initials: "GM",
      label: "Authorized Signatory",
    },
    supervisor: {
      name: "Supervisor",
      title: "SUPERVISOR",
      initials: "SUP",
      label: "Authorized Signatory",
    },
    authorized: {
      name: "General Manager",
      title: "General Manager",
      initials: "GM",
      label: "Authorized Signatory",
    },
  } satisfies {
    humanResources: HrSignatoryProfile;
    generalManager: HrSignatoryProfile;
    supervisor: HrSignatoryProfile;
    authorized: HrSignatoryProfile;
  };
}

function getInitialsFromName(value: string) {
  return value
    .split(/\s+/)
    .map((part) => part.replace(/[^A-Za-z0-9]/g, "").charAt(0).toUpperCase())
    .filter(Boolean)
    .slice(0, 4)
    .join("") || "SG";
}

function getDefaultExecutiveSignatoryTitle(companyName: string) {
  const cleanName = safeString(companyName, "the organization");
  if (/solva business group/i.test(cleanName)) {
    return `C.E.O ${cleanName}`;
  }
  return `General Manager - ${cleanName}`;
}

async function getCompanyHrSignatories(companyId: string | null | undefined) {
  const defaults = getDefaultHrSignatories();
  if (!companyId) {
    return defaults;
  }

  const admin = createSupabaseAdminClient();
  const [settingsResult, companyResult, managerResult, hrResult] = await Promise.all([
    admin.from("company_settings").select("branding").eq("company_id", companyId).maybeSingle(),
    admin.from("companies").select("name").eq("id", companyId).maybeSingle(),
    admin
      .from("users")
      .select("full_name, email, employee_id")
      .eq("company_id", companyId)
      .eq("role", "Manager")
      .eq("status", "active")
      .order("employee_id", { ascending: false }),
    admin
      .from("users")
      .select("full_name, email")
      .eq("company_id", companyId)
      .eq("role", "HR Admin")
      .eq("status", "active")
      .limit(1),
  ]);

  if (settingsResult.error) {
    throw settingsResult.error;
  }
  if (companyResult.error) {
    throw companyResult.error;
  }
  if (managerResult.error) {
    throw managerResult.error;
  }
  if (hrResult.error) {
    throw hrResult.error;
  }

  const companyName = safeString((companyResult.data as Record<string, unknown> | null)?.name, "the organization");
  const branding = asRecord((settingsResult.data as Record<string, unknown> | null)?.branding);
  const signatories = asRecord(branding?.hrSignatories);
  const managerRows = (managerResult.data as Array<Record<string, unknown>> | null) ?? [];
  const managerRecord =
    managerRows.find((row) => Boolean(safeString(row.employee_id))) ??
    managerRows[0] ??
    null;
  const hrRecord = ((hrResult.data as Array<Record<string, unknown>> | null) ?? [])[0] ?? null;
  const computedAuthorized = managerRecord
    ? {
        name: safeString(managerRecord.full_name, safeString(managerRecord.email, defaults.authorized.name ?? defaults.authorized.title)),
        title: getDefaultExecutiveSignatoryTitle(companyName),
        initials: getInitialsFromName(safeString(managerRecord.full_name, safeString(managerRecord.email, "Manager"))),
        label: "Authorized Signatory",
      }
    : {
        ...defaults.authorized,
        name: defaults.authorized.name,
        title: getDefaultExecutiveSignatoryTitle(companyName),
        initials: getInitialsFromName(defaults.authorized.name ?? defaults.authorized.title),
      };
  const computedHr = hrRecord
    ? {
        name: safeString(hrRecord.full_name, safeString(hrRecord.email, defaults.humanResources.name ?? defaults.humanResources.title)),
        title: defaults.humanResources.title,
        initials: getInitialsFromName(safeString(hrRecord.full_name, safeString(hrRecord.email, "HR Admin"))),
        label: "Authorized Signatory",
      }
    : defaults.humanResources;

  function readProfile(key: string, fallback: HrSignatoryProfile, computed?: HrSignatoryProfile) {
    const value = asRecord(signatories?.[key]);
    return {
      name: safeString(value?.name, computed?.name ?? fallback.name),
      title: safeString(value?.title, computed?.title ?? fallback.title),
      initials: safeString(value?.initials, computed?.initials ?? fallback.initials),
      label: safeString(value?.label, computed?.label ?? fallback.label),
    };
  }

  return {
    humanResources: readProfile("humanResources", defaults.humanResources, computedHr),
    generalManager: readProfile("generalManager", defaults.generalManager, computedAuthorized),
    supervisor: readProfile("supervisor", defaults.supervisor),
    authorized: readProfile("authorized", defaults.authorized, computedAuthorized),
  };
}

const PAYROLL_TEMPLATE_OUTPUT_TYPE_SET = new Set<string>(PAYROLL_TEMPLATE_OUTPUT_TYPES);
type PayrollExportType = PayrollTemplateOutputType | SupplementaryPayrollOutputType;

const BANK_BRANCH_CODE_MAP: Record<string, string> = {
  "Kenyatta Avenue": "001",
  "Moi Avenue": "002",
  "Kimathi Street": "003",
  Westlands: "004",
};

function isPayrollTemplateOutputType(value: string): value is PayrollTemplateOutputType {
  return PAYROLL_TEMPLATE_OUTPUT_TYPE_SET.has(value);
}

function slugify(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function formatGeneratedTimestamp(value: string) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) {
    return value;
  }

  return new Intl.DateTimeFormat("en-KE", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "Africa/Nairobi",
  }).format(date);
}

function inferBankBranchCode(branchName: string) {
  if (/^\d+$/.test(branchName.trim())) {
    return branchName.trim();
  }

  return BANK_BRANCH_CODE_MAP[branchName.trim()] ?? "";
}

function titleFromEmployee(row: EmployeeRow) {
  return `${safeString(row.first_name)} ${safeString(row.last_name)}`.trim();
}

function mapEmployeeUserAccount(row: Record<string, unknown> | null | undefined) {
  const status = safeString(row?.status).toLowerCase();
  const activationState = safeString(row?.activation_state);
  const isSuspended = ["suspended", "deactivated", "revoked"].includes(status);
  return {
    status: !row?.id
      ? ("No account" as const)
      : status === "invited"
        ? ("Invited" as const)
        : isSuspended
          ? ("Suspended" as const)
          : ("Active" as const),
    userId: safeString(row?.id) || null,
    role: safeString(row?.role, "-"),
    lastLogin: safeString(row?.last_login, "-"),
    activationState: activationState || "-",
  };
}

function mapEmployeeRecord(row: EmployeeRow): EmployeeRecord {
  const linkedUser = asRecord(row.linked_user);
  const salaryStopActive = isSalaryStoppedEmployee(row);
  const baseStatus = safeString(row.status, "active");
  return {
    id: safeString(row.id),
    employeeNumber: safeString(row.employee_number),
    fullName: titleFromEmployee(row),
    department: safeString((row.department as { name?: string } | null)?.name, "Unassigned"),
    branch: safeString((row.branch as { name?: string } | null)?.name, "Unassigned"),
    employmentType: safeString(row.employment_type, "Unknown"),
    status: salaryStopActive ? `${baseStatus} | Salary stopped` : baseStatus,
    salaryStopActive,
    salaryStopReason: safeString(row.salary_stop_reason),
    salaryStopEffectiveDate: safeString(row.salary_stop_effective_date),
    userAccount: mapEmployeeUserAccount(linkedUser),
  };
}

function mapEmployeeProfile(
  row: EmployeeRow,
  documents: Array<Record<string, unknown>>,
  movements: Array<Record<string, unknown>>,
  leaveHistory: Array<Record<string, unknown>>
): EmployeeProfile {
  const record = mapEmployeeRecord(row);
  const supervisor = asRecord(row.supervisor);
  const linkedUser = asRecord(row.linked_user);
  const invitedBy = asRecord(row.invited_by_user);

  return {
    ...record,
    branchId: safeString(row.branch_id) || null,
    supervisorEmployeeId: safeString(row.supervisor_employee_id) || null,
    phoneNumber: safeString(row.phone, "-"),
    companyEmail: safeString(row.email, "-"),
    profilePhoto: safeString((row as Record<string, unknown>).profile_photo),
    currentGrossPay: safeNumber(row.salary),
    gender: safeString(row.gender, "-"),
    dateOfBirth: safeString(row.date_of_birth, "-"),
    supervisor: supervisor
      ? `${safeString(supervisor.first_name)} ${safeString(supervisor.last_name)}`.trim()
      : "Unassigned",
    costCenter: safeString((row.department as { code?: string } | null)?.code, "-"),
    nationalId: safeString(row.national_id, "-"),
    kraPin: safeString(row.kra_pin, "-"),
    shifNumber: safeString(row.shif_number, "-"),
    nssfNumber: safeString(row.nssf_number, "-"),
    bankName: safeString(row.bank_name, "-"),
    bankAccount: safeString(row.bank_account, "-"),
    hireDate: safeString(row.hire_date, "-"),
    profileSections: [
      {
        title: "Personal and contact",
        items: [
          { label: "Gender", value: safeString(row.gender, "-") },
          { label: "Date of birth", value: safeString(row.date_of_birth, "-") },
          { label: "Phone", value: safeString(row.phone, "-") },
          { label: "Company email", value: safeString(row.email, "-") },
          { label: "Branch", value: safeString((row.branch as { name?: string } | null)?.name, "-") },
          { label: "Department", value: safeString((row.department as { name?: string } | null)?.name, "-") },
        ],
      },
      {
        title: "Employment and reporting",
        items: [
          { label: "Hire date", value: safeString(row.hire_date, "-") },
          { label: "Supervisor", value: supervisor ? `${safeString(supervisor.first_name)} ${safeString(supervisor.last_name)}`.trim() : "Unassigned" },
          { label: "Designation", value: safeString((row.designation as { title?: string } | null)?.title, "-") },
          { label: "Job grade", value: safeString((row.job_grade as { name?: string } | null)?.name, "-") },
          { label: "Monthly Gross Pay", value: String(safeNumber(row.salary)) },
          { label: "Salary status", value: isSalaryStoppedEmployee(row) ? "Stopped from payroll" : "Live in payroll" },
        ],
      },
      {
        title: "Statutory and bank",
        items: [
          { label: "National ID", value: safeString(row.national_id, "-") },
          { label: "KRA PIN", value: safeString(row.kra_pin, "-") },
          { label: "SHIF", value: safeString(row.shif_number, "-") },
          { label: "NSSF", value: safeString(row.nssf_number, "-") },
          { label: "Bank", value: `${safeString(row.bank_name, "-")} ${safeString(row.bank_account, "")}`.trim() },
        ],
      },
    ],
    documentSummary: documents.map((document) => ({
      id: safeString(document.id),
      name: safeString(document.file_name),
      category: safeString(document.category),
      documentType: safeString(document.document_type),
      status: "Uploaded",
      expiry: safeString(document.uploaded_at, "N/A"),
      uploadedAt: safeString(document.uploaded_at),
    })),
    movementHistory: movements.map((movement) => ({
      id: safeString(movement.id),
      title: safeString(movement.action),
      detail: safeString(movement.approval_action || movement.entity_type || movement.module_key),
      date: safeString(movement.created_at),
    })),
    leaveHistory: leaveHistory.map((request) => ({
      id: safeString(request.id),
      leaveType: safeString(request.leave_type),
      requestCategory: safeString(request.request_category, "leave"),
      startDate: safeString(request.start_date),
      endDate: safeString(request.end_date),
      days: safeNumber(request.days),
      status: safeString(request.status),
      createdAt: safeString(request.created_at),
    })),
    userAccountDetail: {
      ...mapEmployeeUserAccount(linkedUser),
      invitedAt: safeString(linkedUser?.invited_at, "-"),
      invitedBy: invitedBy ? safeString(invitedBy.full_name, safeString(invitedBy.email, "-")) : "-",
    },
  };
}

function mapApprovalTask(row: TaskRow): ApprovalTask {
  const requester = asRecord(row.requester);
  const metadata = asRecord(row.metadata);
  const employeeName = safeString(
    metadata?.employeeName,
    safeString(metadata?.fullName, safeString(metadata?.employee_name))
  );
  const departmentName = safeString(
    metadata?.departmentName,
    safeString(metadata?.department, safeString(metadata?.department_name, "Unassigned"))
  );
  const requestType = safeString(
    metadata?.requestType,
    toTitle(safeString(row.entity_type).replace(/_/g, " "))
  );
  const employeeId = safeString(metadata?.employeeId);
  const requesterName = safeString(
    metadata?.requestedByName,
    safeString(
      metadata?.employeeName,
      safeString(requester?.full_name, safeString(requester?.email, safeString(row.requested_by)))
    )
  );
  const taskId = safeString(row.id);

  return {
    id: taskId,
    kind: safeString(row.entity_type) as ApprovalTask["kind"],
    moduleKey: safeString(row.module_key),
    entityId: safeString(row.entity_id),
    employeeId: employeeId || undefined,
    requestType,
    title: safeString(row.title),
    description: safeString(row.description),
    ownerRole: safeString(row.owner_role),
    employee: employeeName || requesterName || "-",
    department: departmentName || "-",
    requestedBy: requesterName,
    requestedByName: requesterName || undefined,
    requestedByRole: safeString(metadata?.requestedByRole, safeString(requester?.role, "Employee")),
    status: (safeString(row.status) as ApprovalTask["status"]) || "pending",
    stage: safeString(row.stage),
    due: safeString(row.due_at, "-"),
    submittedDate: safeString(row.created_at),
    priority: safeString(metadata?.priority, "Normal"),
    pendingApprover: safeString(row.owner_role, safeString(row.stage)),
    latestComment: safeString(
      metadata?.latestApproverComment,
      safeString(metadata?.response, safeString(metadata?.latestComment))
    ),
    linkHref:
      employeeId && taskId
        ? `/?module=ess&item=My%20Requests&entityType=approval_task&entityId=${encodeURIComponent(taskId)}`
        : undefined,
    updatedAt: safeString(row.updated_at, safeString(row.created_at)),
  };
}

function sortApprovalTasksByRecency(tasks: ApprovalTask[]) {
  return [...tasks].sort((left, right) =>
    safeString(right.submittedDate || right.updatedAt).localeCompare(safeString(left.submittedDate || left.updatedAt))
  );
}

async function listSupplementalPerformanceApprovalTasks(context: RequestContext): Promise<ApprovalTask[]> {
  const scopedEmployeeIds = await getScopedEmployeeIds(context);
  let query = context.supabase
    .from("appraisal_reviews")
    .select(
      "id, employee_id, review_cycle, status, created_at, updated_at, self_submitted_at, supervisor_submitted_at, self_comments, supervisor_comments, cycle:cycle_id(title, period_start, period_end), employee:employee_id(id, employee_number, first_name, last_name, department:department_id(name))"
    )
    .in("status", ["supervisor_review_pending", "gm_review_pending"])
    .order("updated_at", { ascending: false })
    .limit(200);

  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }

  query = applyScopedEmployeeIds(query as never, scopedEmployeeIds) as typeof query;

  const { data, error } = await query;
  if (error) {
    throw error;
  }

  const rows = (data ?? []) as Array<Record<string, unknown>>;
  return rows.flatMap((row) => {
    const status = safeString(row.status);
    const employee = asRecord(row.employee);
    const cycle = asRecord(row.cycle);
    const employeeId = safeString(row.employee_id, safeString(employee?.id));
    const employeeNumber = safeString(employee?.employee_number);
    const employeeName =
      `${employeeNumber} ${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim();
    const departmentName = safeString(asRecord(employee?.department)?.name, "Unassigned");
    const cycleTitle = safeString(cycle?.title, safeString(row.review_cycle, "Appraisal Review"));
    const periodStart = safeString(cycle?.period_start);
    const periodEnd = safeString(cycle?.period_end);
    const periodLabel =
      periodStart && periodEnd
        ? `${formatDateLabel(periodStart)} - ${formatDateLabel(periodEnd)}`
        : safeString(row.review_cycle, cycleTitle);

    if (status === "supervisor_review_pending") {
      if (!["Supervisor", "Manager", "HR Admin", "Super Admin"].includes(context.profile.role)) {
        return [];
      }

      return [
        {
          id: `performance-review-${safeString(row.id)}`,
          kind: "performance_review",
          moduleKey: "performance",
          entityId: safeString(row.id),
          employeeId: employeeId || undefined,
          requestType: "Performance Appraisal",
          title: `${cycleTitle} review for ${employeeName || "employee"}`,
          description: `Self-review submitted. ${employeeName || "Employee"} is waiting for supervisor review.`,
          ownerRole: "Supervisor",
          employee: employeeName || "-",
          department: departmentName,
          requestedBy: employeeName || "-",
          requestedByName: employeeName || undefined,
          requestedByRole: "Employee",
          status: "pending",
          stage: "Supervisor appraisal review",
          due: "-",
          submittedDate: safeString(row.self_submitted_at, safeString(row.created_at)),
          priority: "Normal",
          pendingApprover: "Supervisor",
          latestComment: `Period: ${periodLabel}`,
          linkHref: `/?module=performance&item=Performance%20Reviews&entityType=appraisal_review&entityId=${encodeURIComponent(safeString(row.id))}`,
          updatedAt: safeString(row.updated_at, safeString(row.created_at)),
        },
      ];
    }

    if (status === "gm_review_pending") {
      if (!["Manager", "HR Admin", "Super Admin"].includes(context.profile.role)) {
        return [];
      }

      return [
        {
          id: `performance-review-${safeString(row.id)}`,
          kind: "performance_review",
          moduleKey: "performance",
          entityId: safeString(row.id),
          employeeId: employeeId || undefined,
          requestType: "Performance Appraisal",
          title: `${cycleTitle} final review for ${employeeName || "employee"}`,
          description: `Supervisor review is complete. ${employeeName || "Employee"} is waiting for GM or HR final review.`,
          ownerRole: context.profile.role === "HR Admin" ? "HR Admin" : "Manager",
          employee: employeeName || "-",
          department: departmentName,
          requestedBy: employeeName || "-",
          requestedByName: employeeName || undefined,
          requestedByRole: "Employee",
          status: "pending",
          stage: "GM / HR appraisal review",
          due: "-",
          submittedDate: safeString(row.supervisor_submitted_at, safeString(row.created_at)),
          priority: "Normal",
          pendingApprover: "GM / HR Admin",
          latestComment: `Period: ${periodLabel}`,
          linkHref: `/?module=performance&item=Performance%20Reviews&entityType=appraisal_review&entityId=${encodeURIComponent(safeString(row.id))}`,
          updatedAt: safeString(row.updated_at, safeString(row.created_at)),
        },
      ];
    }

    return [];
  });
}

function mapAuditEvent(row: Record<string, unknown>): AuditEvent {
  return {
    id: safeString(row.id),
    moduleKey: safeString(row.module_key),
    category: safeString(row.entity_type),
    action: safeString(row.action),
    actorEmail: safeString(row.actor_email),
    actorName: safeString(row.actor_name),
    actorRole: safeString(row.actor_role),
    actorTitle: safeString(row.actor_title),
    actorDepartment: safeString(row.actor_department),
    subject: safeString(row.approval_action || row.entity_type),
    outcome: safeString(row.action),
    timestamp: safeString(row.created_at),
  };
}

function mapPayrollPackage(row: PayrollRunRow): PayrollPackage {
  const status = normalisePayrollStatus(safeString(row.status, "Draft"));
  const lifecycleLabels = ["Draft", "Open", "Processing", "Pending Approval", "Approved", "Closed", "Reopened"];
  const currentIndex = Math.max(lifecycleLabels.indexOf(status), 0);
  const pendingApprovals = safeNumber(row.pending_approvals, 0);

  return {
    runId: safeString(row.id),
    period: safeString(row.period_label, "Current period"),
    status,
    payrollType: getPayrollTypeLabel(safeString(row.payroll_type, "Full Monthly Payroll")),
    employeeCount: String(safeNumber(row.employee_count, 0)),
    grossPay: formatCurrency(safeNumber(row.gross_pay, 0)),
    netPay: formatCurrency(safeNumber(row.net_pay, 0)),
    totalDeductions: formatCurrency(safeNumber(row.total_deductions, 0)),
    employerCost: formatCurrency(safeNumber(row.employer_cost, 0)),
    paye: formatCurrency(safeNumber(row.paye_total, 0)),
    shif: formatCurrency(safeNumber(row.shif_total, 0)),
    nssf: formatCurrency(safeNumber(row.nssf_total, 0)),
    housingLevy: formatCurrency(safeNumber(row.housing_levy_total, 0)),
    pension: formatCurrency(safeNumber(row.pension_total, 0)),
    validationErrors: safeNumber(row.validation_errors, 0),
    pendingApprovals,
    allowedActions: getPayrollAllowedActions(status),
    lifecycle: lifecycleLabels.map((label, index) => ({
      label,
      status:
        label === status
          ? "current"
          : currentIndex > 0 && index < currentIndex && label !== "Reopened"
            ? "completed"
            : "upcoming",
    })),
  };
}

const PAYROLL_STATUS_SEQUENCE = [
  "Draft",
  "Open",
  "Processing",
  "Pending Approval",
  "Approved",
  "Closed",
  "Reopened",
] as const;

function roundPayrollAmount(value: number) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function getPayrollAllowedActions(status: string) {
  switch (status) {
    case "Draft":
      return ["process", "undo"];
    case "Open":
      return ["process", "undo"];
    case "Processing":
      return ["send_for_approval", "undo"];
    case "Approved":
      return ["close", "reopen", "undo"];
    case "Closed":
      return ["reopen"];
    case "Reopened":
      return ["process", "send_for_approval", "undo"];
    default:
      return [];
  }
}

function getPayrollPeriodBounds(run: PayrollRunRow) {
  const metadata = asRecord(run.metadata);
  const year = safeString(metadata?.period_year);
  const month = safeString(metadata?.period_month).padStart(2, "0");
  const fallbackLabel = safeString(run.period_label);
  const payrollType = normalisePayrollType(safeString(run.payroll_type, "Full Month"));

  let start: Date;
  if (/^\d{4}$/.test(year) && /^\d{2}$/.test(month)) {
    start = new Date(`${year}-${month}-01T00:00:00.000Z`);
  } else {
    start = new Date(`${fallbackLabel.replace(/\s+/g, " ")} 01 00:00:00 UTC`);
  }

  if (Number.isNaN(start.getTime())) {
    const now = new Date();
    start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
  }

  const monthStart = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth(), 1));
  const monthEnd = new Date(Date.UTC(monthStart.getUTCFullYear(), monthStart.getUTCMonth() + 1, 0));
  const end =
    payrollType === "15th Payroll"
      ? new Date(Date.UTC(monthStart.getUTCFullYear(), monthStart.getUTCMonth(), 15))
      : payrollType === "Month-End Payroll"
        ? monthEnd
        : monthEnd;
  start =
    payrollType === "Month-End Payroll"
      ? new Date(Date.UTC(monthStart.getUTCFullYear(), monthStart.getUTCMonth(), 16))
      : monthStart;

  return {
    start,
    end,
    daysInMonth: monthEnd.getUTCDate(),
  };
}

function getPayrollPeriodParts(run: PayrollRunRow) {
  const metadata = asRecord(run.metadata);
  const period = getPayrollPeriodBounds(run).start;
  const monthDate =
    /^\d{4}$/.test(safeString(metadata?.period_year)) && /^\d{2}$/.test(safeString(metadata?.period_month))
      ? new Date(
          `${safeString(metadata?.period_year)}-${safeString(metadata?.period_month)}-01T00:00:00.000Z`
        )
      : period;

  return {
    long: monthDate.toLocaleString("en-KE", {
      month: "long",
      year: "numeric",
      timeZone: "UTC",
    }),
    alt: monthDate.toLocaleString("en-KE", {
      month: "long",
      year: "numeric",
      timeZone: "UTC",
    }).replace(" ", "-"),
    csv: monthDate
      .toLocaleString("en-KE", {
        month: "long",
        year: "numeric",
        timeZone: "UTC",
      })
      .toUpperCase(),
    dated: (safeString(run.processed_at) ? new Date(safeString(run.processed_at)) : new Date()).toLocaleString(
      "en-KE",
      {
        day: "2-digit",
        month: "short",
        year: "numeric",
        timeZone: "Africa/Nairobi",
      }
    ),
  };
}

function diffInDaysInclusive(start: Date, end: Date) {
  const oneDay = 1000 * 60 * 60 * 24;
  return Math.max(1, Math.floor((end.getTime() - start.getTime()) / oneDay) + 1);
}

function addUtcDays(date: Date, days: number) {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate() + days));
}

function buildDateKeySetForOverlap(
  rangeStart: Date,
  rangeEnd: Date,
  windowStart: Date,
  windowEnd: Date
) {
  const effectiveStart = rangeStart > windowStart ? rangeStart : windowStart;
  const effectiveEnd = rangeEnd < windowEnd ? rangeEnd : windowEnd;
  const keys = new Set<string>();

  if (effectiveEnd < effectiveStart) {
    return keys;
  }

  let cursor = new Date(
    Date.UTC(effectiveStart.getUTCFullYear(), effectiveStart.getUTCMonth(), effectiveStart.getUTCDate())
  );
  const last = new Date(
    Date.UTC(effectiveEnd.getUTCFullYear(), effectiveEnd.getUTCMonth(), effectiveEnd.getUTCDate())
  );

  while (cursor <= last) {
    keys.add(cursor.toISOString().slice(0, 10));
    cursor = addUtcDays(cursor, 1);
  }

  return keys;
}

function normalisePayrollType(value: string) {
  const payrollType = safeString(value, "Full Monthly Payroll");

  if (payrollType === "Half Month" || payrollType === "15th Payroll" || payrollType === "MID-MONTH PAYROLL") {
    return "15th Payroll";
  }

  if (payrollType === "Full Month" || payrollType === "Full Monthly Payroll") {
    return "Full Monthly Payroll";
  }

  if (payrollType === "Month-End Payroll" || payrollType === "30th Payroll" || payrollType === "30th / Month-End Payroll") {
    return "Month-End Payroll";
  }

  return payrollType;
}

function getPayrollTypeLabel(value: string) {
  return normalisePayrollType(value);
}

function isMidMonthPayrollType(value: string) {
  return normalisePayrollType(value) === "15th Payroll";
}

function isMonthEndPayrollType(value: string) {
  return normalisePayrollType(value) === "Month-End Payroll";
}

function isFullMonthlyPayrollType(value: string) {
  return normalisePayrollType(value) === "Full Monthly Payroll";
}

function isOffboardedEmployeeStatus(status: unknown) {
  const normalized = safeString(status).trim().toLowerCase();
  return OFFBOARDED_EMPLOYEE_STATUSES.some((value) => normalized.includes(value));
}

function isSalaryStoppedEmployee(row: Record<string, unknown> | null | undefined) {
  if (!row) {
    return false;
  }

  const flag = row.salary_stop_active;
  if (typeof flag === "boolean") {
    return flag;
  }

  const normalized = safeString(flag).trim().toLowerCase();
  return normalized === "true" || normalized === "1" || normalized === "yes";
}

function getMonthlyCalendarBounds(run: PayrollRunRow) {
  const { start } = getPayrollPeriodBounds({
    ...run,
    payroll_type: "Full Monthly Payroll",
  });
  const monthStart = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth(), 1));
  const monthEnd = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth() + 1, 0));
  return {
    start: monthStart,
    end: monthEnd,
    daysInMonth: monthEnd.getUTCDate(),
  };
}

function getEmploymentFactorForBounds(employee: EmployeeRow, start: Date, end: Date, daysInMonth: number) {
  const hireDateValue = safeString(employee.hire_date);
  const contractEndValue = safeString(employee.contract_end_date);
  const hireDate = hireDateValue ? new Date(`${hireDateValue}T00:00:00.000Z`) : null;
  const contractEnd = contractEndValue ? new Date(`${contractEndValue}T00:00:00.000Z`) : null;
  const effectiveStart = hireDate && hireDate > start ? hireDate : start;
  const effectiveEnd = contractEnd && contractEnd < end ? contractEnd : end;

  if (effectiveEnd < effectiveStart) {
    return 0;
  }

  return roundPayrollAmount(diffInDaysInclusive(effectiveStart, effectiveEnd) / daysInMonth);
}

function getEmploymentDaysForBounds(employee: EmployeeRow, start: Date, end: Date) {
  const hireDateValue = safeString(employee.hire_date);
  const contractEndValue = safeString(employee.contract_end_date);
  const hireDate = hireDateValue ? new Date(`${hireDateValue}T00:00:00.000Z`) : null;
  const contractEnd = contractEndValue ? new Date(`${contractEndValue}T00:00:00.000Z`) : null;
  const effectiveStart = hireDate && hireDate > start ? hireDate : start;
  const effectiveEnd = contractEnd && contractEnd < end ? contractEnd : end;

  if (effectiveEnd < effectiveStart) {
    return 0;
  }

  return diffInDaysInclusive(effectiveStart, effectiveEnd);
}

function getMidMonthProrationFactor(employee: EmployeeRow, run: PayrollRunRow) {
  const { start, end, daysInMonth } = getPayrollPeriodBounds({
    ...run,
    payroll_type: "15th Payroll",
  });
  const hireDateValue = safeString(employee.hire_date);
  const hireDate = hireDateValue ? new Date(`${hireDateValue}T00:00:00.000Z`) : null;
  const employmentFactor = getEmploymentFactorForBounds(employee, start, end, daysInMonth);

  if (
    hireDate &&
    hireDate.getUTCFullYear() === start.getUTCFullYear() &&
    hireDate.getUTCMonth() === start.getUTCMonth() &&
    hireDate >= start &&
    hireDate <= end
  ) {
    return employmentFactor;
  }

  return employmentFactor >= 0.5 ? 0.5 : employmentFactor;
}

function getMonthEndProrationFactor(employee: EmployeeRow, run: PayrollRunRow) {
  const { start, end, daysInMonth } = getPayrollPeriodBounds({
    ...run,
    payroll_type: "Month-End Payroll",
  });
  const hireDateValue = safeString(employee.hire_date);
  const hireDate = hireDateValue ? new Date(`${hireDateValue}T00:00:00.000Z`) : null;
  const employmentFactor = getEmploymentFactorForBounds(employee, start, end, daysInMonth);

  if (
    hireDate &&
    hireDate.getUTCFullYear() === start.getUTCFullYear() &&
    hireDate.getUTCMonth() === start.getUTCMonth() &&
    hireDate >= start &&
    hireDate <= end
  ) {
    return employmentFactor;
  }

  return employmentFactor >= 0.5 ? 0.5 : employmentFactor;
}

function getProrationFactor(
  employee: EmployeeRow,
  run: PayrollRunRow
) {
  const { start, end, daysInMonth } = getPayrollPeriodBounds(run);
  const payrollType = normalisePayrollType(safeString(run.payroll_type, "Full Monthly Payroll"));

  if (payrollType === "15th Payroll") {
    return getMidMonthProrationFactor(employee, run);
  }

  if (payrollType === "Month-End Payroll") {
    return getMonthEndProrationFactor(employee, run);
  }

  if (payrollType === "Weekly") {
    return roundPayrollAmount(Math.min(1, 7 / Math.max(daysInMonth, 1)));
  }

  if (payrollType === "Off-Cycle" || payrollType === "Bonus Payroll") {
    return 0;
  }

  return getEmploymentFactorForBounds(employee, start, end, daysInMonth);
}

function getMonthlySalaryFactor(employee: EmployeeRow, run: PayrollRunRow) {
  const { start, end, daysInMonth } = getMonthlyCalendarBounds(run);
  return getEmploymentFactorForBounds(employee, start, end, daysInMonth);
}

function getJsonAmount(map: Record<string, unknown> | null, keys: string[], fallback = 0) {
  if (!map) return fallback;
  for (const key of keys) {
    if (key in map) {
      return safeNumber(map[key], fallback);
    }
  }
  return fallback;
}

function normalisePayrollComponentLookupKey(value: string) {
  return safeString(value).trim().toLowerCase().replace(/[\s_-]+/g, " ");
}

function getUnknownJsonEntries(map: Record<string, unknown> | null, knownKeys: string[]) {
  if (!map) {
    return {} as Record<string, number>;
  }

  const known = new Set(knownKeys.map((key) => normalisePayrollComponentLookupKey(key)));
  const entries: Record<string, number> = {};
  Object.entries(map).forEach(([key, rawValue]) => {
    if (known.has(normalisePayrollComponentLookupKey(key))) {
      return;
    }
    const amount = roundPayrollAmount(safeNumber(rawValue));
    if (amount <= 0) {
      return;
    }
    entries[key] = amount;
  });
  return entries;
}

function calculateKenyaPaye(taxableIncome: number) {
  const bands = [
    { size: 24000, rate: 0.1 },
    { size: 8333, rate: 0.25 },
    { size: 467667, rate: 0.3 },
    { size: 300000, rate: 0.325 },
    { size: Number.POSITIVE_INFINITY, rate: 0.35 },
  ];

  let remaining = Math.max(0, taxableIncome);
  let totalTax = 0;

  for (const band of bands) {
    if (remaining <= 0) break;
    const taxableSlice = Math.min(remaining, band.size);
    totalTax += taxableSlice * band.rate;
    remaining -= taxableSlice;
  }

  return roundPayrollAmount(totalTax);
}

const getRequestContext = cache(async (): Promise<RequestContext> => {
  const authSupabase = await createSupabaseServerClient();
  const supabase = createSupabaseAdminClient();
  const {
    data: { user },
  } = await authSupabase.auth.getUser();

  if (!user) {
    throw new Error("unauthorized");
  }

  const { data } = await supabase
    .from("users")
    .select("id, company_id, full_name, email, phone, role, employee_id, branch_id, department_id, last_login, status")
    .eq("id", user.id)
    .single();

  const metadataStatus =
    typeof user.app_metadata.status === "string"
      ? user.app_metadata.status
      : typeof user.user_metadata.status === "string"
        ? user.user_metadata.status
        : "active";

  const profile: AuthUserProfile = data
    ? {
        ...data,
        role: normalizeRole(safeString(data.role)),
        status:
          safeString(data.status).toLowerCase() === "pending_approval" || metadataStatus === "pending_approval"
            ? "pending_approval"
            : safeString(data.status, metadataStatus),
      }
    : {
        id: user.id,
        company_id: null,
        full_name: safeString(user.user_metadata.full_name, user.email ?? "Solva User"),
        email: user.email ?? "",
        phone: null,
        role: normalizeRole(safeString(user.app_metadata.role, "Employee")),
        employee_id: null,
        branch_id: null,
        department_id: null,
        last_login: null,
        status: metadataStatus,
      };

  if (["pending_approval", "suspended", "deactivated", "revoked"].includes(profile.status.toLowerCase())) {
    throw new Error("forbidden");
  }

  return { supabase, profile };
});

function ensureRole(profile: AuthUserProfile, allowedRoles: AppRole[]) {
  if (!allowedRoles.includes(profile.role)) {
    throw new Error("forbidden");
  }
}

function getRobotCafeSupervisorApproval(profile: AuthUserProfile) {
  if (profile.role === "Supervisor") {
    return {
      ownerRole: "Manager" as AppRole,
      stage: "General Manager review",
    };
  }

  return {
    ownerRole: "Supervisor" as AppRole,
    stage: "Supervisor review",
  };
}

type LeavePolicyRow = Record<string, unknown>;

