export async function createLeaveRequest(input: {
  employeeName: string;
  leaveType: string;
  startDate: string;
  endDate?: string;
  days?: string;
  reason?: string;
  requestCategory?: string;
  leaveAddress?: string;
  contactPhone?: string;
  cellPhone?: string;
  relievingOfficer?: string;
  attachmentNote?: string;
}) {
  const context = await getRequestContext();
  await ensureDefaultLeaveSetup(context);

  let employeeId = context.profile.employee_id;
  let employeeRow: Record<string, unknown> | null = null;
  if (employeeId) {
    const employeeResult = await context.supabase
      .from("employees")
      .select("id, employee_number, first_name, last_name, hire_date, department:department_id(name), designation:designation_id(title), phone, supervisor_employee_id")
      .eq("id", employeeId)
      .maybeSingle();
    if (employeeResult.error) {
      throw employeeResult.error;
    }
    employeeRow = (employeeResult.data as Record<string, unknown> | null) ?? null;
  }

  if (!employeeId && context.profile.role === "Employee") {
    throw new Error("employee_profile_required");
  }

  if (!employeeId) {
    const [firstName, ...rest] = input.employeeName.trim().split(/\s+/);
    const lastName = rest.join(" ");
    const employeeResult = await context.supabase
      .from("employees")
      .select("id, employee_number, first_name, last_name, hire_date, department:department_id(name), designation:designation_id(title), phone, supervisor_employee_id")
      .eq("company_id", context.profile.company_id)
      .eq("first_name", firstName)
      .eq("last_name", lastName || firstName)
      .maybeSingle();

    if (employeeResult.error) {
      throw employeeResult.error;
    }

    employeeRow = (employeeResult.data as Record<string, unknown> | null) ?? null;
    employeeId = safeString(employeeRow?.id);
  }

  if (!employeeId) {
    throw new Error("employee_profile_required");
  }

  const policy = await getLeavePolicyRecord(context, input.leaveType);
  const startDate = new Date(`${input.startDate}T00:00:00.000Z`);
  const endDate = input.endDate
    ? new Date(`${input.endDate}T00:00:00.000Z`)
    : new Date(startDate);
  if (!input.endDate && input.days) {
    endDate.setUTCDate(endDate.getUTCDate() + Number(input.days || 1) - 1);
  }

  const duration = await calculateLeaveDuration(context, {
    startDate: toDateOnlyString(startDate),
    endDate: toDateOnlyString(endDate),
    requestCategory: safeString(input.requestCategory, safeString(policy.request_category, "leave")),
  });
  const requestedDays = input.days ? Number(input.days) : duration.days;
  const balanceRow = await getEmployeeLeaveBalanceRow(
    context,
    employeeId,
    input.leaveType,
    safeString(employeeRow?.hire_date)
  );
  const reducingBalance = Boolean(policy.reducing_balance);
  const balanceBefore = safeNumber(balanceRow.balance_days);
  const pendingBefore = safeNumber(balanceRow.pending_days);
  const pendingAfter = reducingBalance ? pendingBefore + requestedDays : pendingBefore;
  const balanceAfterApproval = reducingBalance ? Math.max(0, balanceBefore - requestedDays) : balanceBefore;
  const payrollImpact = Boolean(policy.payroll_impact);
  const routing = buildLeaveApprovalRouting(context.profile, policy);
  const requestCategory = safeString(input.requestCategory, safeString(policy.request_category, "leave"));

  if (
    reducingBalance &&
    safeNumber(policy.annual_allowance) > 0 &&
    requestedDays > balanceBefore
  ) {
    throw new Error("insufficient_leave_balance");
  }

  const { data, error } = await context.supabase
    .from("leave_requests")
    .insert({
      company_id: context.profile.company_id,
      employee_id: employeeId,
      leave_type: input.leaveType,
      request_category: requestCategory,
      start_date: startDate.toISOString().slice(0, 10),
      end_date: endDate.toISOString().slice(0, 10),
      expected_resume_date: duration.expectedResumeDate,
      days: requestedDays,
      reason: input.reason || `Requested by ${input.employeeName}`,
      status: "pending",
      payroll_impact: payrollImpact,
      details: {
        leaveAddress: input.leaveAddress ?? "",
        contactPhone: input.contactPhone ?? safeString(employeeRow?.phone, context.profile.phone ?? ""),
        cellPhone: input.cellPhone ?? safeString(employeeRow?.phone, context.profile.phone ?? ""),
        relievingOfficer: input.relievingOfficer ?? "",
        attachmentNote: input.attachmentNote ?? "",
        entitlement: safeNumber(policy.annual_allowance),
        accruedDays: safeNumber(balanceRow.accrued_days),
        takenDays: safeNumber(balanceRow.taken_days),
        pendingDaysBefore: pendingBefore,
        pendingDaysAfter: pendingAfter,
        balanceBefore,
        balanceAfterApproval,
        reducingBalance,
        separateTracking: Boolean(policy.separate_tracking),
        requestCategory,
      },
      created_by: context.profile.id,
    })
    .select("id")
    .single();

  if (error || !data) {
    throw error ?? new Error("leave_request_failed");
  }

  const taskRow = await createTask(context, {
    module_key: "leave",
    entity_type: "leave_request",
    entity_id: safeString(data.id),
    title: `${input.leaveType} request for ${input.employeeName}`,
    description: `${requestedDays} day(s) starting ${input.startDate}`,
    owner_role: routing.ownerRole,
    stage: routing.stage,
    metadata: {
      requestType: requestCategory === "off_day" ? "Off Day" : "Leave",
      final_status: "approved",
      next_owner_role: routing.nextOwnerRole || null,
      next_stage: routing.nextStage || null,
      allowed_approver_roles: routing.allowedApproverRoles,
      employeeId,
      employeeName: input.employeeName,
      departmentName: safeString(asRecord(employeeRow?.department)?.name),
      priority: requestedDays > 10 ? "High" : "Normal",
      request_category: requestCategory,
      payroll_impact: payrollImpact,
    },
  });

  await context.supabase
    .from("leave_requests")
    .update({ approval_task_id: taskRow.id })
    .eq("id", data.id);

  await createAuditLog(context, {
    moduleKey: "leave",
    entityType: "leave_request",
    entityId: safeString(data.id),
    action: "created_leave_request",
    afterValue: {
      leave_type: input.leaveType,
      days: requestedDays,
      start_date: input.startDate,
      end_date: endDate.toISOString().slice(0, 10),
      expected_resume_date: duration.expectedResumeDate,
    },
  });

  if (employeeId && reducingBalance) {
    await adjustLeaveBalance(context, employeeId, input.leaveType, {
      pendingDelta: requestedDays,
    });
  }

  return mapApprovalTask(taskRow);
}

export async function updateLeaveRequestRecord(input: {
  requestId: string;
  action: "cancel" | "update";
  leaveType?: string;
  startDate?: string;
  endDate?: string;
  days?: string;
  reason?: string;
}) {
  const context = await getRequestContext();

  const { data: existing, error } = await context.supabase
    .from("leave_requests")
    .select("id, employee_id, leave_type, start_date, end_date, days, status, created_by")
    .eq("id", input.requestId)
    .maybeSingle();

  if (error || !existing) {
    throw error ?? new Error("leave_request_not_found");
  }

  if (
    safeString(existing.created_by) !== context.profile.id &&
    !["Super Admin", "HR Admin", "Manager", "Supervisor"].includes(context.profile.role)
  ) {
    throw new Error("forbidden");
  }

  if (input.action === "cancel") {
    await context.supabase.from("leave_requests").update({ status: "cancelled" }).eq("id", input.requestId);
    const policy = await getLeavePolicyRecord(context, safeString(existing.leave_type));
    if (Boolean(policy.reducing_balance)) {
      await adjustLeaveBalance(context, safeString(existing.employee_id), safeString(existing.leave_type), {
        pendingDelta: -safeNumber(existing.days),
      });
    }
    await createAuditLog(context, {
      moduleKey: "leave",
      entityType: "leave_request",
      entityId: input.requestId,
      action: "cancelled_leave_request",
      beforeValue: existing,
      afterValue: { status: "cancelled" },
    });
    return { id: input.requestId, status: "cancelled" };
  }

  const nextDays = Number(input.days ?? safeNumber(existing.days));
  const nextStart = input.startDate ?? safeString(existing.start_date);
  const nextEnd = input.endDate ?? safeString(existing.end_date);

  await context.supabase
    .from("leave_requests")
    .update({
      leave_type: input.leaveType ?? safeString(existing.leave_type),
      start_date: nextStart,
      end_date: nextEnd,
      days: nextDays,
      reason: input.reason ?? null,
      status: "pending",
    })
    .eq("id", input.requestId);

  await createAuditLog(context, {
    moduleKey: "leave",
    entityType: "leave_request",
    entityId: input.requestId,
    action: "updated_leave_request",
    beforeValue: existing,
    afterValue: {
      leave_type: input.leaveType ?? safeString(existing.leave_type),
      start_date: nextStart,
      end_date: nextEnd,
      days: nextDays,
      reason: input.reason ?? null,
    },
  });

  return { id: input.requestId, status: "pending" };
}

