export async function listLeaveBalances() {
  const context = await getRequestContext();
  const scopedEmployeeIds = await getScopedEmployeeIds(context);
  await ensureLeaveBalancesForScopedEmployees(context, scopedEmployeeIds);

  let query = context.supabase
    .from("leave_balances")
    .select(
      "id, employee_id, leave_type, opening_balance, accrued_days, taken_days, pending_days, balance_days, as_of_date, employee:employee_id(employee_number, first_name, last_name, salary, hire_date, department:department_id(name), branch:branch_id(name))"
    )
    .order("as_of_date", { ascending: false })
    .limit(250);

  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }

  query = applyScopedEmployeeIds(query as never, scopedEmployeeIds) as typeof query;

  const { data, error } = await query;

  if (error) {
    throw error;
  }

  const rows = (data ?? []) as Array<Record<string, unknown>>;
  const { data: policies, error: policiesError } = await context.supabase
    .from("leave_policies")
    .select("leave_type, annual_allowance, monthly_accrual_rate, accrual_frequency, reducing_balance")
    .eq("company_id", context.profile.company_id);
  if (policiesError) {
    throw policiesError;
  }

  const policyMap = new Map(
    (policies ?? []).map((policy) => [safeString(policy.leave_type), policy as Record<string, unknown>])
  );
  let employeeGender = "";
  if (context.profile.role === "Employee" && context.profile.employee_id) {
    const { data: employeeRow } = await context.supabase
      .from("employees")
      .select("gender")
      .eq("id", context.profile.employee_id)
      .maybeSingle();
    employeeGender = safeString(employeeRow?.gender).toLowerCase();
  }

  const normalizedRows: Array<Record<string, unknown>> = [];
  for (const row of rows) {
    const policy = policyMap.get(safeString(row.leave_type));
    if (!policy) {
      normalizedRows.push(row);
      continue;
    }
    const genderApplicability = safeString(policy.gender_applicability, "all").toLowerCase();
    if (employeeGender && genderApplicability !== "all" && genderApplicability !== employeeGender) {
      continue;
    }

    const employee = asRecord(row.employee);
    const annualAllowance = safeNumber(policy.annual_allowance);
    const monthlyAccrualRate = safeNumber(policy.monthly_accrual_rate);
    const accrualFrequency = safeString(policy.accrual_frequency);
    const reducingBalance = Boolean(policy.reducing_balance);
    const hireDate = safeString(employee?.hire_date);
    const hireMonth = hireDate ? new Date(`${hireDate}T00:00:00.000Z`).getUTCMonth() + 1 : 1;
    const monthsElapsed = Math.max(0, new Date().getUTCMonth() + 1 - Math.max(hireMonth, 1) + 1);
    const accruedDays =
      accrualFrequency === "monthly"
        ? Math.min(annualAllowance || Number.POSITIVE_INFINITY, roundPayrollAmount(monthlyAccrualRate * monthsElapsed))
        : annualAllowance;
    const takenDays = safeNumber(row.taken_days);
    const displayBase = annualAllowance > 0 ? annualAllowance : accruedDays;
    const balanceDays = reducingBalance ? Math.max(0, roundPayrollAmount(displayBase - takenDays)) : displayBase;

    normalizedRows.push({
      ...row,
      opening_balance: annualAllowance,
      accrued_days: accruedDays,
      balance_days: balanceDays,
    });
  }

  return normalizedRows;
}

