export async function listLatenessAndAbsenteeism() {
  const context = await getRequestContext();
  const scopedEmployeeIds = await getScopedEmployeeIds(context);

  let latenessQuery = context.supabase
    .from("lateness_records")
    .select("id, employee_id, work_date, minutes_late, status, notes, employee:employee_id(employee_number, first_name, last_name, department:department_id(name))")
    .order("work_date", { ascending: false })
    .limit(120);

  let absenceQuery = context.supabase
    .from("absenteeism_records")
    .select("id, employee_id, work_date, absence_type, status, notes, employee:employee_id(employee_number, first_name, last_name, department:department_id(name))")
    .order("work_date", { ascending: false })
    .limit(120);

  let exceptionQuery = context.supabase
    .from("attendance_exceptions")
    .select("id, employee_id, work_date, exception_type, severity, status, payroll_relevant, notes, employee:employee_id(employee_number, first_name, last_name)")
    .order("work_date", { ascending: false })
    .limit(120);

  if (context.profile.company_id) {
    latenessQuery = latenessQuery.eq("company_id", context.profile.company_id);
    absenceQuery = absenceQuery.eq("company_id", context.profile.company_id);
    exceptionQuery = exceptionQuery.eq("company_id", context.profile.company_id);
  }

  latenessQuery = applyScopedEmployeeIds(latenessQuery as never, scopedEmployeeIds) as typeof latenessQuery;
  absenceQuery = applyScopedEmployeeIds(absenceQuery as never, scopedEmployeeIds) as typeof absenceQuery;
  exceptionQuery = applyScopedEmployeeIds(exceptionQuery as never, scopedEmployeeIds) as typeof exceptionQuery;

  const [{ data: lateness, error: latenessError }, { data: absence, error: absenceError }, { data: exceptions, error: exceptionError }] = await Promise.all([
    latenessQuery,
    absenceQuery,
    exceptionQuery,
  ]);

  if (latenessError) throw latenessError;
  if (absenceError) throw absenceError;
  if (exceptionError) throw exceptionError;

  return {
    lateness: (lateness ?? []) as Array<Record<string, unknown>>,
    absence: (absence ?? []) as Array<Record<string, unknown>>,
    exceptions: (exceptions ?? []) as Array<Record<string, unknown>>,
    summary: {
      openExceptions: (exceptions ?? []).filter((row) => safeString((row as Record<string, unknown>).status) !== "closed").length,
      lateCount: (lateness ?? []).length,
      absenceCount: (absence ?? []).length,
    },
  };
}

