export async function createPayrollDayDeduction(input: {
  employeeId: string;
  deductionMode?: string;
  deductionCategory: string;
  deductionDays?: number | string;
  fixedAmount?: number | string;
  startDate: string;
  endDate?: string;
  targetPayrollRunId?: string;
  targetPayrollLabel?: string;
  reason: string;
  notes?: string;
}) {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Super Admin", "HR Admin", "Payroll Admin", "Manager", "Supervisor"]);
  await assertEmployeeScope(context, input.employeeId);

  const deductionMode = safeString(input.deductionMode, "day_count") === "incident_amount" ? "incident_amount" : "day_count";
  const startDate = parseDateOnlyUtc(input.startDate, "invalid_deduction_start_date");
  const endDate = parseDateOnlyUtc(input.endDate ?? input.startDate, "invalid_deduction_end_date");

  if (endDate < startDate) {
    throw new Error("invalid_deduction_date_range");
  }

  const parsedDeductionDays = roundPayrollAmount(
    Math.max(0, safeNumber(input.deductionDays, countOverlappingDaysInclusive(startDate, endDate, startDate, endDate)))
  );
  const fixedAmount = roundPayrollAmount(Math.max(0, safeNumber(input.fixedAmount, 0)));

  if (deductionMode === "day_count" && parsedDeductionDays <= 0) {
    throw new Error("invalid_deduction_days");
  }

  if (deductionMode === "incident_amount" && fixedAmount <= 0) {
    throw new Error("invalid_fixed_deduction_amount");
  }

  const admin = createSupabaseAdminClient();

  const { data: employee, error: employeeError } = await admin
    .from("employees")
    .select("id, employee_number, first_name, last_name, salary")
    .eq("id", input.employeeId)
    .eq("company_id", safeString(context.profile.company_id))
    .maybeSingle();

  if (employeeError || !employee) {
    throw employeeError ?? new Error("employee_not_found");
  }

  const requiresApproval = context.profile.role === "Supervisor";
  const insertPayload = {
    company_id: context.profile.company_id,
    employee_id: input.employeeId,
    adjustment_type: "payroll_deduction",
    work_date: startDate.toISOString().slice(0, 10),
    end_date: endDate.toISOString().slice(0, 10),
    deduction_mode: deductionMode,
    deduction_days: deductionMode === "day_count" ? parsedDeductionDays : 0,
    fixed_amount: deductionMode === "incident_amount" ? fixedAmount : 0,
    deduction_category: safeString(input.deductionCategory, "Unworked Days"),
    target_payroll_run_id: safeString(input.targetPayrollRunId) || null,
    target_payroll_label: safeString(input.targetPayrollLabel) || null,
    reason: safeString(input.reason),
    notes: safeString(input.notes),
    status: requiresApproval ? "pending" : "approved",
    requested_by: context.profile.id,
    created_by_role: context.profile.role,
  };

  const { data, error } = await admin
    .from("attendance_adjustments")
    .insert(insertPayload)
    .select(
      "id, employee_id, work_date, end_date, deduction_mode, deduction_days, fixed_amount, deduction_category, target_payroll_run_id, target_payroll_label, reason, notes, status, created_at, created_by_role, approval_task_id, employee:employee_id(employee_number, first_name, last_name, department:department_id(name), branch:branch_id(name))"
    )
    .single();

  if (error || !data) {
    throw error ?? new Error("payroll_day_deduction_create_failed");
  }

  if (requiresApproval) {
    const employeeName = `${safeString(employee.first_name)} ${safeString(employee.last_name)}`.trim();
    const task = await createTask(context, {
      module_key: "payroll",
      entity_type: "payroll_day_deduction",
      entity_id: safeString(data.id),
      title: `Review payroll deduction for ${employeeName}`,
      description:
        deductionMode === "incident_amount"
          ? `${safeString(employee.employee_number)} | ${insertPayload.deduction_category} | KES ${fixedAmount.toLocaleString()}`
          : `${safeString(employee.employee_number)} | ${insertPayload.deduction_category} | ${parsedDeductionDays} day(s)`,
      owner_role: "Manager",
      stage: "GM / Payroll / HR deduction review",
      metadata: {
        requestType: "Payroll Deduction",
        employeeId: input.employeeId,
        employeeName,
        employeeNumber: safeString(employee.employee_number),
        deductionMode,
        deductionCategory: insertPayload.deduction_category,
        startDate: insertPayload.work_date,
        endDate: insertPayload.end_date,
        deductionDays: parsedDeductionDays,
        fixedAmount,
        targetPayrollRunId: insertPayload.target_payroll_run_id,
        targetPayrollLabel: insertPayload.target_payroll_label,
        reason: insertPayload.reason,
        notes: insertPayload.notes,
        allowed_approver_roles: ["Manager", "HR Admin", "Payroll Admin", "Super Admin"],
        final_status: "approved",
      },
    });

    await admin.from("attendance_adjustments").update({ approval_task_id: task.id }).eq("id", safeString(data.id));
  }

  await createAuditLog(context, {
    moduleKey: "payroll",
    entityType: "payroll_day_deduction",
    entityId: safeString(data.id),
    action: "created_payroll_day_deduction",
    afterValue: {
      employeeId: input.employeeId,
      employeeNumber: safeString(employee.employee_number),
      employeeName: `${safeString(employee.first_name)} ${safeString(employee.last_name)}`.trim(),
      deductionMode,
      deductionCategory: insertPayload.deduction_category,
      startDate: insertPayload.work_date,
      endDate: insertPayload.end_date,
      deductionDays: parsedDeductionDays,
      fixedAmount,
      targetPayrollRunId: insertPayload.target_payroll_run_id,
      targetPayrollLabel: insertPayload.target_payroll_label,
      reason: insertPayload.reason,
      notes: insertPayload.notes,
      workflowStatus: insertPayload.status,
    },
  });

  return (await listPayrollDayDeductions()).find((row) => safeString(row.id) === safeString(data.id)) ?? {
    id: safeString(data.id),
    employeeId: input.employeeId,
    employeeNumber: safeString(employee.employee_number),
    employeeName: `${safeString(employee.first_name)} ${safeString(employee.last_name)}`.trim(),
    department: "",
    branch: "",
    startDate: insertPayload.work_date,
    endDate: insertPayload.end_date,
    deductionMode,
    deductionDays: parsedDeductionDays,
    fixedAmount,
    deductionCategory: insertPayload.deduction_category,
    targetPayrollRunId: safeString(insertPayload.target_payroll_run_id),
    targetPayrollLabel: safeString(insertPayload.target_payroll_label),
    reason: insertPayload.reason,
    notes: insertPayload.notes,
    status: requiresApproval ? "pending" : "approved",
    createdAt: new Date().toISOString(),
    createdByRole: context.profile.role,
  };
}

export async function approvePayrollDayDeduction(deductionId: string, comments?: string) {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Super Admin", "HR Admin", "Payroll Admin", "Manager"]);

  const admin = createSupabaseAdminClient();
  const { data: existing, error: existingError } = await admin
    .from("attendance_adjustments")
    .select("*")
    .eq("id", deductionId)
    .eq("company_id", safeString(context.profile.company_id))
    .eq("adjustment_type", "payroll_deduction")
    .maybeSingle();

  if (existingError || !existing) {
    throw existingError ?? new Error("payroll_day_deduction_not_found");
  }

  await assertEmployeeScope(context, safeString(existing.employee_id));

  const nextNotes = [safeString(existing.notes), safeString(comments)].filter(Boolean).join(" | ");

  const { data, error } = await admin
    .from("attendance_adjustments")
    .update({
      status: "approved",
      notes: nextNotes,
    })
    .eq("id", deductionId)
    .select("*")
    .single();

  if (error || !data) {
    throw error ?? new Error("payroll_day_deduction_approve_failed");
  }

  const approvalTaskId = safeString(existing.approval_task_id);
  if (approvalTaskId) {
    const { data: existingTask } = await admin
      .from("approval_tasks")
      .select("metadata")
      .eq("id", approvalTaskId)
      .maybeSingle();

    await admin
      .from("approval_tasks")
      .update({
        status: "approved",
        stage: "Completed",
        updated_at: new Date().toISOString(),
        metadata: {
          ...(asRecord(existingTask?.metadata) ?? {}),
          latestApproverComment: safeString(comments, "Approved payroll deduction recommendation."),
        },
      })
      .eq("id", approvalTaskId);
  }

  await createAuditLog(context, {
    moduleKey: "payroll",
    entityType: "payroll_day_deduction",
    entityId: deductionId,
    action: "approved_payroll_day_deduction",
    beforeValue: existing as Record<string, unknown>,
    afterValue: data as Record<string, unknown>,
    approvalAction: safeString(comments, "approve"),
  });

  await notifyEmployeeAction(context, {
    employeeId: safeString(existing.employee_id),
    entityType: "payroll_day_deduction",
    entityId: deductionId,
    title: "Salary deduction approved",
    message: `A salary deduction has been approved for your upcoming payroll. Reason: ${safeString(existing.reason, "Operational adjustment")}.`,
    category: "payroll",
  });

  return { success: true };
}

