export async function createPayrollAddition(input: {
  employeeId: string;
  earningCategory: string;
  amount: number | string;
  effectiveDate: string;
  targetPayrollRunId?: string;
  targetPayrollLabel?: string;
  reason: string;
  notes?: string;
}) {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Super Admin", "HR Admin", "Payroll Admin", "Manager", "Supervisor"]);
  await assertEmployeeScope(context, input.employeeId);

  const amount = roundPayrollAmount(Math.max(0, safeNumber(input.amount, 0)));
  if (amount <= 0) {
    throw new Error("invalid_payroll_addition_amount");
  }

  const effectiveDate = parseDateOnlyUtc(input.effectiveDate, "invalid_payroll_addition_effective_date");
  const admin = createSupabaseAdminClient();

  const { data: employee, error: employeeError } = await admin
    .from("employees")
    .select("id, employee_number, first_name, last_name")
    .eq("id", input.employeeId)
    .eq("company_id", safeString(context.profile.company_id))
    .maybeSingle();

  if (employeeError || !employee) {
    throw employeeError ?? new Error("employee_not_found");
  }

  let targetPayrollRunId = safeString(input.targetPayrollRunId);
  let targetPayrollLabel = safeString(input.targetPayrollLabel);

  if (!targetPayrollRunId && context.profile.company_id) {
    const { data: nextRun } = await admin
      .from("payroll_runs")
      .select("id, period_label")
      .eq("company_id", safeString(context.profile.company_id))
      .in("status", ["Open", "Processing", "Reopened", "Draft"])
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    targetPayrollRunId = safeString(nextRun?.id);
    targetPayrollLabel = safeString(nextRun?.period_label);
  }

  const requiresApproval = context.profile.role === "Supervisor";
  const insertPayload = {
    company_id: context.profile.company_id,
    employee_id: input.employeeId,
    adjustment_type: "payroll_addition",
    work_date: effectiveDate.toISOString().slice(0, 10),
    deduction_mode: "incident_amount",
    deduction_category: safeString(input.earningCategory, "Bonus"),
    fixed_amount: amount,
    target_payroll_run_id: targetPayrollRunId || null,
    target_payroll_label: targetPayrollLabel || null,
    reason: safeString(input.reason),
    notes: safeString(input.notes),
    status: requiresApproval ? "pending" : "approved",
    requested_by: context.profile.id,
    created_by_role: context.profile.role,
  };

  const { data, error } = await admin
    .from("attendance_adjustments")
    .insert(insertPayload)
    .select("id")
    .single();

  if (error || !data) {
    throw error ?? new Error("payroll_addition_create_failed");
  }

  if (requiresApproval) {
    const employeeName = `${safeString(employee.first_name)} ${safeString(employee.last_name)}`.trim();
    const task = await createTask(context, {
      module_key: "payroll",
      entity_type: "payroll_addition",
      entity_id: safeString(data.id),
      title: `Review ${safeString(input.earningCategory, "bonus")} for ${employeeName}`,
      description: `${safeString(employee.employee_number)} | KES ${amount.toLocaleString()}`,
      owner_role: "Manager",
      stage: "GM / Payroll / HR payroll addition review",
      metadata: {
        requestType: "Payroll Addition",
        employeeId: input.employeeId,
        employeeName,
        employeeNumber: safeString(employee.employee_number),
        earningCategory: safeString(input.earningCategory, "Bonus"),
        fixedAmount: amount,
        effectiveDate: insertPayload.work_date,
        targetPayrollRunId: insertPayload.target_payroll_run_id,
        targetPayrollLabel: insertPayload.target_payroll_label,
        reason: insertPayload.reason,
        notes: insertPayload.notes,
        allowed_approver_roles: ["Manager", "HR Admin", "Payroll Admin", "Super Admin"],
        final_status: "approved",
      },
    });
    await admin.from("attendance_adjustments").update({ approval_task_id: task.id }).eq("id", safeString(data.id));
  }

  await createAuditLog(context, {
    moduleKey: "payroll",
    entityType: "payroll_addition",
    entityId: safeString(data.id),
    action: "created_payroll_addition",
    afterValue: {
      employeeId: input.employeeId,
      employeeNumber: safeString(employee.employee_number),
      employeeName: `${safeString(employee.first_name)} ${safeString(employee.last_name)}`.trim(),
      earningCategory: safeString(input.earningCategory, "Bonus"),
      amount,
      effectiveDate: insertPayload.work_date,
      targetPayrollRunId: insertPayload.target_payroll_run_id,
      targetPayrollLabel: insertPayload.target_payroll_label,
      workflowStatus: insertPayload.status,
    },
  });

  return (await listPayrollAdditions()).find((row) => safeString(row.id) === safeString(data.id));
}

export async function approvePayrollAddition(additionId: string, comments?: string) {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Super Admin", "HR Admin", "Payroll Admin", "Manager"]);

  const admin = createSupabaseAdminClient();
  const { data: existing, error: existingError } = await admin
    .from("attendance_adjustments")
    .select("*")
    .eq("id", additionId)
    .eq("company_id", safeString(context.profile.company_id))
    .eq("adjustment_type", "payroll_addition")
    .maybeSingle();

  if (existingError || !existing) {
    throw existingError ?? new Error("payroll_addition_not_found");
  }

  await assertEmployeeScope(context, safeString(existing.employee_id));

  const nextNotes = [safeString(existing.notes), safeString(comments)].filter(Boolean).join(" | ");

  const { data, error } = await admin
    .from("attendance_adjustments")
    .update({ status: "approved", notes: nextNotes })
    .eq("id", additionId)
    .select("*")
    .single();

  if (error || !data) {
    throw error ?? new Error("payroll_addition_approve_failed");
  }

  const approvalTaskId = safeString(existing.approval_task_id);
  if (approvalTaskId) {
    await admin
      .from("approval_tasks")
      .update({
        status: "approved",
        stage: "Completed",
        updated_at: new Date().toISOString(),
      })
      .eq("id", approvalTaskId);
  }

  await createAuditLog(context, {
    moduleKey: "payroll",
    entityType: "payroll_addition",
    entityId: additionId,
    action: "approved_payroll_addition",
    beforeValue: existing as Record<string, unknown>,
    afterValue: data as Record<string, unknown>,
    approvalAction: safeString(comments, "approve"),
  });

  await notifyEmployeeAction(context, {
    employeeId: safeString(existing.employee_id),
    entityType: "payroll_addition",
    entityId: additionId,
    title: "Payroll addition approved",
    message: `An extra payment has been approved for your upcoming payroll. Reason: ${safeString(existing.reason, "Payroll addition")}.`,
    category: "payroll",
  });

  return { success: true };
}

export async function voidPayrollAddition(additionId: string, reason?: string) {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Super Admin", "HR Admin", "Payroll Admin", "Manager", "Supervisor"]);

  const admin = createSupabaseAdminClient();
  const { data: existing, error: existingError } = await admin
    .from("attendance_adjustments")
    .select("*")
    .eq("id", additionId)
    .eq("company_id", safeString(context.profile.company_id))
    .eq("adjustment_type", "payroll_addition")
    .maybeSingle();

  if (existingError || !existing) {
    throw existingError ?? new Error("payroll_addition_not_found");
  }

  await assertEmployeeScope(context, safeString(existing.employee_id));

  const nextNotes = [safeString(existing.notes), safeString(reason)].filter(Boolean).join(" | ");

  const { data, error } = await admin
    .from("attendance_adjustments")
    .update({ status: "voided", notes: nextNotes })
    .eq("id", additionId)
    .select("*")
    .single();

  if (error || !data) {
    throw error ?? new Error("payroll_addition_void_failed");
  }

  const approvalTaskId = safeString(existing.approval_task_id);
  if (approvalTaskId) {
    await admin
      .from("approval_tasks")
      .update({
        status: "rejected",
        stage: `Voided by ${context.profile.role}`,
        updated_at: new Date().toISOString(),
      })
      .eq("id", approvalTaskId);
  }

  await createAuditLog(context, {
    moduleKey: "payroll",
    entityType: "payroll_addition",
    entityId: additionId,
    action: "voided_payroll_addition",
    beforeValue: existing as Record<string, unknown>,
    afterValue: data as Record<string, unknown>,
    approvalAction: safeString(reason, "void"),
  });

  return { success: true };
}

export async function createEssSalaryAdvanceRequest(input: {
  amount: number | string;
  reason: string;
}) {
  const context = await getRequestContext();

  if (!context.profile.employee_id) {
    throw new Error("employee_profile_required");
  }

  const amount = roundPayrollAmount(Math.max(0, safeNumber(input.amount, 0)));
  if (amount <= 0) {
    throw new Error("invalid_salary_advance_amount");
  }

  const reason = safeString(input.reason).trim();
  if (!reason) {
    throw new Error("missing_salary_advance_reason");
  }

  const requestDateIso = new Date().toISOString().slice(0, 10);
  const requestMonthPrefix = requestDateIso.slice(0, 7);
  const admin = createSupabaseAdminClient();

  const { data: employee, error: employeeError } = await admin
    .from("employees")
    .select("id, employee_number, first_name, last_name, supervisor_employee_id")
    .eq("id", context.profile.employee_id)
    .eq("company_id", safeString(context.profile.company_id))
    .maybeSingle();

  if (employeeError || !employee) {
    throw employeeError ?? new Error("employee_not_found");
  }

  const { data: existingRequests, error: existingRequestError } = await admin
    .from("approval_tasks")
    .select("id, created_at, metadata")
    .eq("company_id", safeString(context.profile.company_id))
    .eq("entity_type", "salary_advance_request")
    .order("created_at", { ascending: false })
    .limit(200);

  if (existingRequestError) {
    throw existingRequestError;
  }

  const alreadyRequestedThisMonth = ((existingRequests ?? []) as Array<Record<string, unknown>>).some((row) => {
    const metadata = asRecord((row as Record<string, unknown>).metadata);
    return (
      safeString(metadata?.employeeId) === safeString(context.profile.employee_id) &&
      safeString((row as Record<string, unknown>).created_at).slice(0, 7) === requestMonthPrefix
    );
  });

  if (alreadyRequestedThisMonth) {
    throw new Error("salary_advance_already_requested_this_month");
  }

  const nextRun = await findUpcomingPayrollRunForDate(
    context,
    safeString(context.profile.company_id),
    requestDateIso
  );

  const employeeName = `${safeString(employee.first_name)} ${safeString(employee.last_name)}`.trim();
  const task = await createTask(context, {
    module_key: "payroll",
    entity_type: "salary_advance_request",
    entity_id: safeString(employee.id),
    title: `Salary advance request for ${employeeName}`,
    description: `Requested salary advance of KES ${amount.toLocaleString()}`,
    owner_role: "Supervisor",
    stage: "Supervisor salary advance review",
    metadata: {
      requestType: "Salary Advance",
      employeeId: safeString(employee.id),
      employeeName,
      employeeNumber: safeString(employee.employee_number),
      requestDate: requestDateIso,
      amount,
      reason,
      targetPayrollRunId: nextRun.id,
      targetPayrollLabel: nextRun.periodLabel,
      supervisorEmployeeId: safeString(employee.supervisor_employee_id),
      next_owner_role: "Manager",
      next_stage: "General Manager salary advance approval",
      allowed_approver_roles: ["Supervisor", "Super Admin"],
      final_status: "approved",
    },
  });

  await createAuditLog(context, {
    moduleKey: "payroll",
    entityType: "salary_advance_request",
    entityId: safeString(task.id),
    action: "created_salary_advance_request",
    afterValue: {
      employeeId: safeString(employee.id),
      employeeNumber: safeString(employee.employee_number),
      employeeName,
      amount,
      reason,
      requestDate: requestDateIso,
      targetPayrollRunId: nextRun.id,
      targetPayrollLabel: nextRun.periodLabel,
    },
  });

  return {
    id: safeString(task.id),
    title: safeString(task.title),
    amount: formatCurrency(amount),
    rawAmount: amount,
    reason,
    requestDate: requestDateIso,
    status: safeString(task.status),
    stage: safeString(task.stage),
    targetPayrollLabel: nextRun.periodLabel,
    updatedAt: safeString(task.updated_at, safeString(task.created_at)),
  };
}

async function finalizeSalaryAdvanceRequest(
  context: RequestContext,
  taskRow: TaskRow,
  metadata: Record<string, unknown>
) {
  const employeeId = safeString(metadata.employeeId);
  const amount = roundPayrollAmount(Math.max(0, safeNumber(metadata.amount, 0)));
  const requestDate = safeString(metadata.requestDate);
  const reason = safeString(metadata.reason);
  const companyId = safeString(context.profile.company_id);

  if (!employeeId || amount <= 0 || !requestDate || !companyId) {
    throw new Error("invalid_salary_advance_request");
  }

  const targetRun =
    safeString(metadata.targetPayrollRunId) && safeString(metadata.targetPayrollLabel)
      ? {
          id: safeString(metadata.targetPayrollRunId),
          periodLabel: safeString(metadata.targetPayrollLabel),
        }
      : await findUpcomingPayrollRunForDate(context, companyId, requestDate);

  const admin = createSupabaseAdminClient();
  const existingNotesTag = `salary_advance_task:${safeString(taskRow.id)}`;
  const { data: existingAdjustment, error: existingAdjustmentError } = await admin
    .from("attendance_adjustments")
    .select("id")
    .eq("company_id", companyId)
    .eq("employee_id", employeeId)
    .eq("adjustment_type", "payroll_deduction")
    .eq("target_payroll_run_id", targetRun.id)
    .ilike("notes", `%${existingNotesTag}%`)
    .maybeSingle();

  if (existingAdjustmentError) {
    throw existingAdjustmentError;
  }

  if (!existingAdjustment) {
    const notes = [
      `Salary advance recovery for request on ${requestDate}.`,
      reason ? `Reason: ${reason}` : "",
      existingNotesTag,
    ]
      .filter(Boolean)
      .join(" | ");

    const { error } = await admin.from("attendance_adjustments").insert({
      company_id: companyId,
      employee_id: employeeId,
      adjustment_type: "payroll_deduction",
      work_date: requestDate,
      end_date: requestDate,
      deduction_mode: "incident_amount",
      deduction_days: 0,
      fixed_amount: amount,
      deduction_category: "Salary Advance",
      target_payroll_run_id: targetRun.id,
      target_payroll_label: targetRun.periodLabel,
      reason: "Salary advance recovery",
      notes,
      status: "approved",
      requested_by: safeString(taskRow.requested_by),
      created_by_role: "Employee",
    });

    if (error) {
      throw error;
    }
  }
}

