export async function createLeavePolicy(input: {
  leaveType: string;
  policyName: string;
  annualAllowance: string;
  accrualFrequency?: string;
  monthlyAccrualRate?: string;
  reducingBalance?: boolean;
  carryForwardEnabled?: boolean;
  carryForwardLimit?: string;
  requiresAttachment?: boolean;
  payrollImpact?: boolean;
  requestCategory?: string;
  approvalFlow?: string;
  minimumNoticeDays?: string;
  maxConsecutiveDays?: string;
}) {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Super Admin", "HR Admin"]);
  const fallback = findDefaultLeavePolicyDefinition(input.leaveType);

  await context.supabase.from("leave_types").upsert(
    {
      company_id: context.profile.company_id,
      code: normaliseLeaveCode(input.leaveType),
      name: input.leaveType,
      color: fallback?.color ?? "#475569",
      is_paid: !(input.payrollImpact ?? fallback?.payrollImpact ?? false),
      requires_attachment: input.requiresAttachment ?? fallback?.requiresAttachment ?? false,
      gender_applicability: fallback?.genderApplicability ?? "all",
      status: "active",
    },
    { onConflict: "company_id,code" }
  );

  const { data, error } = await context.supabase
    .from("leave_policies")
    .upsert({
      company_id: context.profile.company_id,
      leave_type: input.leaveType,
      policy_name: input.policyName,
      annual_allowance: Number(input.annualAllowance || 0),
      accrual_frequency: input.accrualFrequency ?? "monthly",
      monthly_accrual_rate: Number(input.monthlyAccrualRate ?? fallback?.monthlyAccrualRate ?? 0),
      reducing_balance: input.reducingBalance ?? fallback?.reducingBalance ?? true,
      carry_forward_enabled: input.carryForwardEnabled ?? fallback?.carryForwardEnabled ?? false,
      carry_forward_limit: Number(input.carryForwardLimit ?? fallback?.carryForwardLimit ?? 0),
      requires_attachment: input.requiresAttachment ?? fallback?.requiresAttachment ?? (input.leaveType === "Sick Leave"),
      payroll_impact: input.payrollImpact ?? fallback?.payrollImpact ?? false,
      counts_toward_balance: fallback?.countsTowardBalance ?? true,
      separate_tracking: fallback?.separateTracking ?? false,
      request_category: input.requestCategory ?? fallback?.category ?? "leave",
      approval_flow: input.approvalFlow ?? fallback?.approvalFlow ?? "supervisor_hr",
      minimum_notice_days: Number(input.minimumNoticeDays ?? fallback?.minimumNoticeDays ?? 0),
      max_consecutive_days: Number(input.maxConsecutiveDays ?? fallback?.maxConsecutiveDays ?? 0),
      status: "active",
    }, { onConflict: "company_id,leave_type" })
    .select("id, leave_type, policy_name")
    .single();

  if (error) {
    throw error;
  }

  return data;
}

export async function getLeaveReportsSnapshot() {
  const [requests, balances, attendance, overtime, lateness] = await Promise.all([
    listLeaveRequests(),
    listLeaveBalances(),
    listAttendanceRecords(),
    listOvertimeRequests(),
    listLatenessAndAbsenteeism(),
  ]);

  const requestsByDepartment = new Map<string, number>();
  for (const request of requests) {
    const department = safeString((asRecord(request.employee)?.department as Record<string, unknown> | null)?.name, "Unassigned");
    requestsByDepartment.set(department, (requestsByDepartment.get(department) ?? 0) + 1);
  }

  return {
    leaveSummary: requests.length,
    attendanceSummary: attendance.length,
    overtimeHours: overtime.reduce((sum, row) => sum + safeNumber(row.hours), 0),
    latenessCount: lateness.summary.lateCount,
    absenceCount: lateness.summary.absenceCount,
    liability: balances.reduce((sum, row) => sum + safeNumber(row.balance_days), 0),
    pendingLeave: requests.filter((row) => safeString(row.status) === "pending").length,
    offDayRequests: requests.filter((row) => safeString(row.request_category) === "off_day").length,
    unpaidLeaveImpact: requests
      .filter((row) => safeString(row.leave_type) === "Unpaid Leave" && safeString(row.status) === "approved")
      .reduce((sum, row) => sum + safeNumber(row.days), 0),
    byDepartment: Array.from(requestsByDepartment.entries()).map(([department, count]) => ({ department, count })),
  };
}

export async function getLeaveRequestDetail(requestId: string) {
  const context = await getRequestContext();
  const scopedEmployeeIds = (await getScopedEmployeeIds(context)) ?? [];

  let query = context.supabase
    .from("leave_requests")
    .select(
      "id, company_id, employee_id, leave_type, request_category, start_date, end_date, expected_resume_date, days, reason, status, payroll_impact, details, final_decision, final_approved_at, employee:employee_id(employee_number, first_name, last_name, phone, hire_date, department:department_id(name), branch:branch_id(name), designation:designation_id(title)), approval_task:approval_task_id(id, owner_role, status, stage)"
    )
    .eq("id", requestId);

  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }

  const { data, error } = await query.maybeSingle();
  if (error || !data) {
    throw error ?? new Error("leave_request_not_found");
  }

  if (context.profile.role !== "Super Admin" && !scopedEmployeeIds.includes(safeString((data as Record<string, unknown>).employee_id))) {
    throw new Error("forbidden");
  }

  const requestRow = data as Record<string, unknown>;
  const employee = asRecord(requestRow.employee);
  const [policy, balanceRowResult, approvalsResult] = await Promise.all([
    getLeavePolicyRecord(context, safeString(requestRow.leave_type)),
    context.supabase
      .from("leave_balances")
      .select("*")
      .eq("employee_id", safeString(requestRow.employee_id))
      .eq("leave_type", safeString(requestRow.leave_type))
      .order("as_of_date", { ascending: false })
      .limit(1)
      .maybeSingle(),
    context.supabase
      .from("leave_approvals")
      .select("approval_stage, owner_role, action, comments, acted_at, actor:acted_by(full_name)")
      .eq("leave_request_id", requestId)
      .order("created_at", { ascending: true }),
  ]);

  if (balanceRowResult.error) {
    throw balanceRowResult.error;
  }
  if (approvalsResult.error) {
    throw approvalsResult.error;
  }

  return {
    request: requestRow,
    employee,
    policy,
    balance: (balanceRowResult.data as Record<string, unknown> | null) ?? null,
    approvals: (approvalsResult.data ?? []) as Array<Record<string, unknown>>,
  };
}

export async function generateLeaveApplicationForm(requestId: string) {
  const detail = await getLeaveRequestDetail(requestId);
  const context = await getRequestContext();
  const request = detail.request;
  const employee = detail.employee;
  const policy = detail.policy;
  const details = asRecord(request.details);
  const branding = await getCompanyBrandingContext(safeString(request.company_id), "Robot Cafe & Bistro", "RCB");
  const supervisorApproval = detail.approvals.find((row) => safeString(row.owner_role) === "Supervisor");
  const finalApproval = [...detail.approvals].reverse().find((row) => ["HR Admin", "Manager", "Super Admin"].includes(safeString(row.owner_role)));
  const entitlement = safeNumber(detail.balance?.opening_balance, safeNumber(policy.annual_allowance));
  const accruedDays = safeNumber(detail.balance?.accrued_days);
  const takenDays = safeNumber(detail.balance?.taken_days);
  const pendingDays = safeNumber(detail.balance?.pending_days);
  const balanceAfterApproval = safeNumber(details?.balanceAfterApproval, safeNumber(detail.balance?.balance_days));
  const applicantName = `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim() || safeString(context.profile.full_name);
  const finalApproverName = safeString(asRecord(finalApproval?.actor)?.full_name);
  const supervisorName = safeString(asRecord(supervisorApproval?.actor)?.full_name, safeString(context.profile.full_name));
  const isUnpaidLeave = safeString(request.leave_type) === "Unpaid Leave";
  const dataset: LeaveApplicationFormDataset = {
    organizationName: branding.organizationName,
    organizationIdentifier: branding.organizationIdentifier,
    organizationLogoMark: branding.organizationLogoMark,
    organizationLogoJpeg: branding.organizationLogoJpeg,
    platformLogoJpeg: branding.platformLogoJpeg,
    organizationAddressLines: branding.organizationAddressLines,
    reportFooter: branding.reportFooter,
    generatedAtLabel: formatDateTimeLabel(new Date().toISOString()),
    formReference: "RCB-LV-F1",
    applicant: {
      name: applicantName,
      designation: safeString(asRecord(employee?.designation)?.name),
      staffNumber: safeString(employee?.employee_number),
      department: safeString(asRecord(employee?.department)?.name),
      workStation: safeString(asRecord(employee?.branch)?.name),
      leaveType: safeString(request.leave_type),
      numberOfDays: safeNumber(request.days),
      fromDate: formatDateLabel(safeString(request.start_date)),
      toDate: formatDateLabel(safeString(request.end_date)),
      expectedResumeDate: formatDateLabel(safeString(request.expected_resume_date)),
      leaveAddress: safeString(details?.leaveAddress),
      telephoneNumber: safeString(details?.contactPhone),
      cellPhone: safeString(details?.cellPhone),
      relievingOfficer: safeString(details?.relievingOfficer),
      attachmentNote:
        safeString(details?.attachmentNote) ||
        (Boolean(policy.requires_attachment) ? "Supporting document required for this leave type." : ""),
    },
    supervisorSection: {
      recommendDays: safeNumber(request.days),
      notRecommendedReason: safeString(request.status) === "rejected" ? safeString(finalApproval?.comments) : "",
      comments: safeString(supervisorApproval?.comments),
      designation: safeString(supervisorApproval?.owner_role, "Supervisor"),
      date: formatDateLabel(safeString(supervisorApproval?.acted_at)),
      name: supervisorName,
    },
    hrComputation: {
      entitlement,
      accruedDays,
      takenDays,
      pendingDays,
      totalDaysDue: accruedDays + Math.max(0, entitlement - accruedDays),
      totalDaysRequested: safeNumber(request.days),
      balanceAfterApproval,
      resumeDate: formatDateLabel(safeString(request.expected_resume_date)),
      computedBy: finalApproverName || "Pending final approval",
      designation: finalApproverName ? safeString(finalApproval?.owner_role) : "HR/Admin",
      date: formatDateLabel(safeString(request.final_approved_at, safeString(finalApproval?.acted_at))),
    },
    payrollImpact: {
      leaveAllowance: isUnpaidLeave ? "Not applicable" : "As per company policy",
      unpaidLeaveDeductionFlag: isUnpaidLeave || Boolean(request.payroll_impact) ? "Yes" : "No",
      payrollMonthAffected: new Date(`${safeString(request.start_date)}T00:00:00.000Z`).toLocaleString("en-KE", {
        month: "long",
        year: "numeric",
        timeZone: "UTC",
      }),
    },
    finalApproval: {
      decision: safeString(request.final_decision, safeString(request.status)).toUpperCase(),
      approvalDate: formatDateLabel(safeString(request.final_approved_at)),
      approverName: finalApproverName || "Pending",
      approverRole: finalApproverName ? safeString(finalApproval?.owner_role) : "HR/Admin",
    },
    reason: safeString(request.reason),
  };

  return buildLeaveApplicationFormPdf(dataset);
}

export async function getPayrollReadyAttendanceSummary() {
  const [requests, overtime, lateness, attendance] = await Promise.all([
    listLeaveRequests(),
    listOvertimeRequests(),
    listLatenessAndAbsenteeism(),
    listAttendanceRecords(),
  ]);

  const summary = new Map<string, {
    employeeName: string;
    unpaidLeaveDays: number;
    approvedOvertimeHours: number;
    lateMinutes: number;
    absenceDays: number;
    payrollExceptions: number;
  }>();

  for (const request of requests) {
    const employee = asRecord(request.employee);
    const key = safeString((request as Record<string, unknown>).employee_id, safeString(employee?.employee_number));
    if (!summary.has(key)) {
      summary.set(key, {
        employeeName: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        unpaidLeaveDays: 0,
        approvedOvertimeHours: 0,
        lateMinutes: 0,
        absenceDays: 0,
        payrollExceptions: 0,
      });
    }
    const current = summary.get(key)!;
    if (safeString(request.leave_type) === "Unpaid Leave" && safeString(request.status) === "approved") {
      current.unpaidLeaveDays += safeNumber(request.days);
    }
  }

  for (const row of overtime) {
    const employee = asRecord(row.employee);
    const key = safeString((row as Record<string, unknown>).employee_id, safeString(employee?.employee_number));
    if (!summary.has(key)) {
      summary.set(key, {
        employeeName: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        unpaidLeaveDays: 0,
        approvedOvertimeHours: 0,
        lateMinutes: 0,
        absenceDays: 0,
        payrollExceptions: 0,
      });
    }
    const current = summary.get(key)!;
    if (safeString(row.status) === "approved") {
      current.approvedOvertimeHours += safeNumber(row.hours);
    }
  }

  for (const row of lateness.lateness) {
    const employee = asRecord(row.employee);
    const key = safeString((row as Record<string, unknown>).employee_id, safeString(employee?.employee_number));
    if (!summary.has(key)) {
      summary.set(key, {
        employeeName: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        unpaidLeaveDays: 0,
        approvedOvertimeHours: 0,
        lateMinutes: 0,
        absenceDays: 0,
        payrollExceptions: 0,
      });
    }
    summary.get(key)!.lateMinutes += safeNumber((row as Record<string, unknown>).minutes_late);
  }

  for (const row of lateness.absence) {
    const employee = asRecord(row.employee);
    const key = safeString((row as Record<string, unknown>).employee_id, safeString(employee?.employee_number));
    if (!summary.has(key)) {
      summary.set(key, {
        employeeName: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        unpaidLeaveDays: 0,
        approvedOvertimeHours: 0,
        lateMinutes: 0,
        absenceDays: 0,
        payrollExceptions: 0,
      });
    }
    summary.get(key)!.absenceDays += 1;
  }

  for (const row of attendance) {
    const employee = asRecord(row.employee);
    const key = safeString((row as Record<string, unknown>).employee_id, safeString(employee?.employee_number));
    if (!summary.has(key)) {
      summary.set(key, {
        employeeName: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        unpaidLeaveDays: 0,
        approvedOvertimeHours: 0,
        lateMinutes: 0,
        absenceDays: 0,
        payrollExceptions: 0,
      });
    }
    if (["absent", "late", "incomplete"].includes(safeString(row.status))) {
      summary.get(key)!.payrollExceptions += 1;
    }
  }

  return Array.from(summary.values());
}

export async function getLeaveSettingsSnapshot() {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Super Admin", "HR Admin", "Payroll Admin", "Manager", "Supervisor", "Auditor"]);

  const [types, policies, weekendRules, holidays, devices] = await Promise.all([
    listLeaveTypes(),
    listLeavePolicies(),
    listWeekendRules(),
    listHolidays(),
    listAttendanceDevices(),
  ]);

  return {
    leaveTypes: types.length,
    policies: policies.length,
    weekendRules: weekendRules.length,
    holidays: holidays.length,
    devices: devices.devices.length,
  };
}

