async function getScopedEmployeeDetailRows(context: RequestContext) {
  let query = context.supabase
    .from("employees")
    .select(
      "id, employee_number, first_name, last_name, gender, date_of_birth, email, phone, employment_type, status, hire_date, confirmation_date, contract_end_date, salary, national_id, kra_pin, shif_number, nssf_number, bank_name, bank_branch, bank_account, department:department_id(name), branch:branch_id(name), designation:designation_id(title), job_grade:job_grade_id(name), supervisor:supervisor_employee_id(first_name, last_name)"
    )
    .order("employee_number", { ascending: true })
    .limit(1000);

  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }

  const scopedEmployeeIds = await getScopedEmployeeIds(context);
  query = applyScopedEmployeeIds(query as never, scopedEmployeeIds, "id") as typeof query;

  const { data, error } = await query;

  if (error) {
    throw error;
  }

  return (data ?? []) as Array<Record<string, unknown>>;
}

async function getLatestPayrollEmployeeRows(context: RequestContext) {
  const run = await getLatestPayrollRun(context);
  if (!run) {
    return { run: null, rows: [] as Array<Record<string, unknown>> };
  }

  const scopedEmployeeIds = await getScopedEmployeeIds(context);

  let query = context.supabase
    .from("payroll_employees")
    .select(
      "id, employee_id, gross_pay, net_pay, deductions, allowances, status, employee:employee_id(employee_number, first_name, last_name, department:department_id(name), branch:branch_id(name))"
    )
    .eq("payroll_run_id", safeString(run.id))
    .order("gross_pay", { ascending: false });

  query = applyScopedEmployeeIds(query as never, scopedEmployeeIds) as typeof query;

  const { data, error } = await query;

  if (error) {
    throw error;
  }

  return { run, rows: (data ?? []) as Array<Record<string, unknown>> };
}

