function countByLabel(items: string[]) {
  const map = new Map<string, number>();
  for (const item of items) {
    map.set(item, (map.get(item) ?? 0) + 1);
  }
  return Array.from(map.entries()).map(([label, value]) => ({ label, value }));
}

function buildAgeBracket(dateValue: string) {
  if (!dateValue) return "Unknown";
  const years = Math.floor((Date.now() - new Date(dateValue).getTime()) / (1000 * 60 * 60 * 24 * 365.25));
  if (years < 25) return "18-24";
  if (years < 35) return "25-34";
  if (years < 45) return "35-44";
  if (years < 55) return "45-54";
  return "55+";
}

function calculateAgeYears(dateValue: string) {
  if (!dateValue) return "";
  const parsed = new Date(`${dateValue}T00:00:00.000Z`);
  if (Number.isNaN(parsed.getTime())) return "";
  const years = Math.floor((Date.now() - parsed.getTime()) / (1000 * 60 * 60 * 24 * 365.25));
  return years >= 0 ? String(years) : "";
}

async function listRecentPayrollRunsInternal(context: RequestContext, limit = 6) {
  let query = context.supabase
    .from("payroll_runs")
    .select(
      "id, period_label, gross_pay, net_pay, employer_cost, total_deductions, paye_total, shif_total, nssf_total, housing_levy_total, pension_total, validation_errors, pending_approvals, status, processed_at, created_at"
    )
    .order("created_at", { ascending: false })
    .limit(limit);

  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }

  const { data, error } = await query;
  if (error) throw error;
  return (data ?? []) as Array<Record<string, unknown>>;
}

async function getPreviousPayrollEmployeeRows(
  context: RequestContext,
  currentRunId: string | null
) {
  if (!currentRunId) {
    return { run: null, rows: [] as Array<Record<string, unknown>> };
  }

  let runsQuery = context.supabase
    .from("payroll_runs")
    .select("id, period_label, gross_pay, net_pay, employer_cost, total_deductions, created_at")
    .neq("id", currentRunId)
    .order("created_at", { ascending: false })
    .limit(1);

  if (context.profile.company_id) {
    runsQuery = runsQuery.eq("company_id", context.profile.company_id);
  }

  const { data: previousRun, error: previousRunError } = await runsQuery.maybeSingle();
  if (previousRunError) throw previousRunError;
  if (!previousRun) {
    return { run: null, rows: [] as Array<Record<string, unknown>> };
  }

  const scopedEmployeeIds = await getScopedEmployeeIds(context);
  let rowsQuery = context.supabase
    .from("payroll_employees")
    .select(
      "id, employee_id, gross_pay, net_pay, deductions, allowances, status, employee:employee_id(employee_number, first_name, last_name, department:department_id(name), branch:branch_id(name))"
    )
    .eq("payroll_run_id", safeString(previousRun.id))
    .order("gross_pay", { ascending: false });

  rowsQuery = applyScopedEmployeeIds(rowsQuery as never, scopedEmployeeIds) as typeof rowsQuery;
  const { data: rows, error: rowsError } = await rowsQuery;
  if (rowsError) throw rowsError;

  return {
    run: previousRun as Record<string, unknown>,
    rows: (rows ?? []) as Array<Record<string, unknown>>,
  };
}

function getPayrollRowTotalDeductions(row: Record<string, unknown>) {
  const deductions = (row.deductions as Record<string, unknown> | null) ?? {};
  return Object.values(deductions).reduce<number>((sum, value) => sum + safeNumber(value), 0);
}

function getPayrollRowAmount(
  bucket: Record<string, unknown> | null | undefined,
  labels: string[]
) {
  return getJsonAmount(bucket ?? null, labels);
}

function getPayrollRowOvertime(row: Record<string, unknown>) {
  return getPayrollRowAmount((row.allowances as Record<string, unknown> | null) ?? {}, [
    "Overtime",
    "overtime",
  ]);
}

function getPayrollRowAdjustment(row: Record<string, unknown>) {
  return getPayrollRowAmount((row.allowances as Record<string, unknown> | null) ?? {}, [
    "Adjustments",
    "Adjustment",
    "adjustments",
  ]);
}

function buildPerformanceBand(score: number) {
  if (score >= 100) return "Exceptional";
  if (score >= 85) return "High";
  if (score >= 70) return "Strong";
  if (score >= 50) return "Stable";
  return "At Risk";
}

function buildTrendLabel(current: number, previous: number, noun: string, formatter: "currency" | "count" | "percent" = "count") {
  const movement = current - previous;
  const movementSign = movement > 0 ? "+" : "";
  const percent = previous > 0 ? Number(((movement / previous) * 100).toFixed(1)) : current > 0 ? 100 : 0;
  const movementValue =
    formatter === "currency"
      ? formatCurrency(Math.abs(movement))
      : formatter === "percent"
        ? `${Math.abs(movement).toFixed(1)} pts`
        : `${Math.abs(movement)}`;

  if (movement === 0) {
    return `${toTitle(noun)} held steady against the previous period.`;
  }

  return `${toTitle(noun)} ${movement > 0 ? "rose" : "fell"} by ${movementValue} (${movementSign}${percent}%).`;
}

function buildPayrollAnomalySummary(input: {
  currentRows: Array<Record<string, unknown>>;
  previousRows: Array<Record<string, unknown>>;
}) {
  const duplicateMap = new Map<string, number>();
  const previousByEmployee = new Map(
    input.previousRows.map((row) => [
      safeString(asRecord(row.employee)?.employee_number || row.employee_id),
      row,
    ])
  );
  const anomalies: Array<Record<string, unknown>> = [];

  for (const row of input.currentRows) {
    const employee = asRecord(row.employee);
    const employeeNumber = safeString(employee?.employee_number || row.employee_id, "Unknown");
    const employeeName =
      `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim() || employeeNumber;
    duplicateMap.set(employeeNumber, (duplicateMap.get(employeeNumber) ?? 0) + 1);

    const grossPay = safeNumber(row.gross_pay);
    const netPay = safeNumber(row.net_pay);
    const totalDeductions = getPayrollRowTotalDeductions(row);
    const overtime = getPayrollRowOvertime(row);
    const adjustments = Math.abs(getPayrollRowAdjustment(row));
    const previousRow = previousByEmployee.get(employeeNumber);
    const previousGross = previousRow ? safeNumber(previousRow.gross_pay) : 0;
    const previousDeductions = previousRow ? getPayrollRowTotalDeductions(previousRow) : 0;
    const shif = getPayrollRowAmount((row.deductions as Record<string, unknown> | null) ?? {}, ["SHIF", "Nhif", "NHIF", "shif"]);
    const nssf = getPayrollRowAmount((row.deductions as Record<string, unknown> | null) ?? {}, ["NSSF", "nssf"]);
    const housingLevy = getPayrollRowAmount((row.deductions as Record<string, unknown> | null) ?? {}, ["Housing Levy", "AHL", "housing levy"]);
    const companyId = safeString(employee?.company_id);
    const safaPolicy = isSafaDairyCompany(companyId)
      ? getSafaDairyStatutoryPolicy(safeString(employee?.employment_type), grossPay, false)
      : null;
    const expectedShif = safaPolicy ? safaPolicy.shif : roundPayrollAmount(grossPay * 0.0275);
    const expectedHousingLevy = safaPolicy
      ? safaPolicy.housingLevy
      : roundPayrollAmount(grossPay * 0.015);
    const expectedNssf = safaPolicy ? safaPolicy.nssf : grossPay > 0 ? 1080 : 0;

    if (netPay < 0) {
      anomalies.push({
        title: "Negative net pay",
        detail: `${employeeName} has a negative net pay of ${formatCurrency(netPay)}.`,
        severity: "critical",
        employeeName,
      });
    }

    if (previousGross > 0 && grossPay > previousGross * 1.2 && grossPay - previousGross >= 5000) {
      anomalies.push({
        title: "Unusual salary increase",
        detail: `${employeeName} moved from ${formatCurrency(previousGross)} to ${formatCurrency(grossPay)}.`,
        severity: "warning",
        employeeName,
      });
    }

    if (overtime > Math.max(10000, grossPay * 0.2)) {
      anomalies.push({
        title: "Abnormal overtime",
        detail: `${employeeName} has overtime worth ${formatCurrency(overtime)} in the current run.`,
        severity: "warning",
        employeeName,
      });
    }

    if (previousDeductions > 0 && totalDeductions > previousDeductions * 1.25 && totalDeductions - previousDeductions >= 3000) {
      anomalies.push({
        title: "Deduction spike",
        detail: `${employeeName} deductions moved from ${formatCurrency(previousDeductions)} to ${formatCurrency(totalDeductions)}.`,
        severity: "warning",
        employeeName,
      });
    }

    if (grossPay > 0 && totalDeductions > grossPay * 0.45) {
      anomalies.push({
        title: "Heavy deduction load",
        detail: `${employeeName} deductions consume ${Math.round((totalDeductions / grossPay) * 100)}% of gross pay.`,
        severity: "warning",
        employeeName,
      });
    }

    if (Math.abs(shif - expectedShif) > 5 || Math.abs(housingLevy - expectedHousingLevy) > 5 || Math.abs(nssf - expectedNssf) > 5) {
      anomalies.push({
        title: "Statutory mismatch",
        detail: `${employeeName} has a statutory mismatch across SHIF, NSSF, or Housing Levy.`,
        severity: "critical",
        employeeName,
      });
    }

    if (adjustments > Math.max(8000, grossPay * 0.15)) {
      anomalies.push({
        title: "Suspicious adjustment",
        detail: `${employeeName} carries an adjustment of ${formatCurrency(adjustments)}.`,
        severity: "warning",
        employeeName,
      });
    }

    if (grossPay <= 0) {
      anomalies.push({
        title: "Missing payroll line",
        detail: `${employeeName} is present in payroll with zero gross pay.`,
        severity: "critical",
        employeeName,
      });
    }
  }

  for (const [employeeNumber, count] of duplicateMap.entries()) {
    if (count > 1) {
      anomalies.push({
        title: "Duplicate payroll entry",
        detail: `${employeeNumber} appears ${count} times in the current payroll run.`,
        severity: "critical",
        employeeName: employeeNumber,
      });
    }
  }

  const severityOrder = { critical: 0, warning: 1, default: 2 } as const;
  return anomalies
    .sort((left, right) => severityOrder[safeString(left.severity, "default") as keyof typeof severityOrder] - severityOrder[safeString(right.severity, "default") as keyof typeof severityOrder])
    .slice(0, 12);
}

function buildForecastSummary(input: {
  recentRuns: Array<Record<string, unknown>>;
  approvedSalaryDelta: number;
  pendingSalaryDelta: number;
  overtimeCost: number;
}) {
  const ordered = [...input.recentRuns].reverse();
  const grossSeries = ordered.map((row) => safeNumber(row.gross_pay));
  const employerSeries = ordered.map((row) => safeNumber(row.employer_cost));
  const averageDelta =
    grossSeries.length > 1
      ? grossSeries.slice(1).reduce((sum, value, index) => sum + (value - grossSeries[index]), 0) /
        (grossSeries.length - 1)
      : 0;
  const currentGross = grossSeries.at(-1) ?? 0;
  const currentEmployerCost = employerSeries.at(-1) ?? 0;
  const projectedGross = roundPayrollAmount(currentGross + averageDelta + input.approvedSalaryDelta + input.pendingSalaryDelta * 0.5);
  const projectedEmployerCost = roundPayrollAmount(
    currentEmployerCost + averageDelta + input.approvedSalaryDelta + input.overtimeCost * 0.3
  );

  return {
    nextMonthWagebill: formatCurrency(Math.max(projectedGross, 0)),
    nextMonthEmployerCost: formatCurrency(Math.max(projectedEmployerCost, 0)),
    projectedAnnualPayroll: formatCurrency(Math.max(projectedGross, 0) * 12),
    promotionImpact: formatCurrency(input.approvedSalaryDelta + input.pendingSalaryDelta),
    overtimeImpact: formatCurrency(input.overtimeCost),
    averageMovement: formatCurrency(Math.abs(averageDelta)),
    movementDirection: averageDelta >= 0 ? "up" : "down",
  };
}

function buildTopBottomPerformanceGroups(reviews: Array<Record<string, unknown>>) {
  const grouped = new Map<
    string,
    { label: string; total: number; count: number; kind: string; managerRatings: number[] }
  >();

  for (const review of reviews) {
    const employee = asRecord(review.employee);
    const performance = derivePerformanceSnapshot(review);
    const label = safeString((employee?.department as Record<string, unknown> | null)?.name, "Unassigned");
    const kind = safeString(performance.subjectRole, "Employee");
    const managerRating = safeNumber(performance.managerRating);
    const bucket = grouped.get(label) ?? { label, total: 0, count: 0, kind, managerRatings: [] };
    bucket.total += performance.achievementPercent || safeNumber(review.score);
    bucket.count += 1;
    if (managerRating > 0) bucket.managerRatings.push(managerRating);
    grouped.set(label, bucket);
  }

  const ranked = Array.from(grouped.values())
    .map((bucket) => ({
      label: bucket.label,
      value: Number((bucket.count ? bucket.total / bucket.count : 0).toFixed(1)),
      display: `${Number((bucket.count ? bucket.total / bucket.count : 0).toFixed(1))}% average achievement`,
      kind: bucket.kind,
    }))
    .sort((left, right) => safeNumber(right.value) - safeNumber(left.value));

  return {
    topTeams: ranked.slice(0, 5),
    underperformingTeams: [...ranked].reverse().slice(0, 5),
  };
}

function buildExecutiveInsights(input: {
  currentGross: number;
  previousGross: number;
  currentNet: number;
  previousNet: number;
  pendingApprovals: number;
  missingDataCount: number;
  anomalies: Array<Record<string, unknown>>;
  reviews: Array<Record<string, unknown>>;
  overtimeCost: number;
}) {
  const insights: Array<{
    title: string;
    detail: string;
    tone: "default" | "positive" | "warning" | "critical";
  }> = [];
  insights.push({
    title: "Payroll movement",
    detail: buildTrendLabel(input.currentGross, input.previousGross, "monthly payroll", "currency"),
    tone: input.currentGross >= input.previousGross ? "warning" : "positive",
  });
  insights.push({
    title: "Net pay movement",
    detail: buildTrendLabel(input.currentNet, input.previousNet, "net pay", "currency"),
    tone: input.currentNet >= input.previousNet ? "default" : "warning",
  });
  if (input.pendingApprovals > 0) {
    insights.push({
      title: "Approval pressure",
      detail: `${input.pendingApprovals} approvals still need attention before operations are fully clear.`,
      tone: "warning",
    });
  }
  if (input.missingDataCount > 0) {
    insights.push({
      title: "Master data gaps",
      detail: `${input.missingDataCount} employee records still have statutory or bank-data gaps affecting operations.`,
      tone: "critical",
    });
  }
  if (input.anomalies.length > 0) {
    insights.push({
      title: "Payroll anomalies detected",
      detail: `${input.anomalies.length} anomaly flags were raised in the latest payroll comparison set.`,
      tone: safeString(input.anomalies[0]?.severity) === "critical" ? "critical" : "warning",
    });
  }
  const recurringLowPerformers = input.reviews.filter((review) => derivePerformanceSnapshot(review).achievementPercent < 70).length;
  if (recurringLowPerformers > 0) {
    insights.push({
      title: "Performance attention",
      detail: `${recurringLowPerformers} performance records are currently tracking below the 70% threshold.`,
      tone: "warning",
    });
  }
  if (input.overtimeCost > 0) {
    insights.push({
      title: "Overtime cost signal",
      detail: `Current overtime value is ${formatCurrency(input.overtimeCost)} and should be reviewed against staffing patterns.`,
      tone: "default",
    });
  }
  return insights.slice(0, 8);
}

export async function getExecutiveDashboardReport() {
  const context = await getRequestContext();
  ensureReportCategoryAccess(context.profile, "executive");

  const [
    employees,
    latestPayroll,
    recentRuns,
    leaveDashboard,
    attendanceDashboard,
    approvalTasks,
    requisitions,
    training,
    assets,
    appraisals,
    overtimeRequests,
    exports,
  ] = await Promise.all([
    getScopedEmployeeDetailRows(context),
    getLatestPayrollEmployeeRows(context),
    listRecentPayrollRunsInternal(context, 6),
    getLeaveDashboardSnapshot(),
    getAttendanceDashboardSnapshot(),
    fetchApprovalTasksInternal(context),
    listRecruitmentRequisitionsInternal(context),
    listTrainingRequestsInternal(context),
    listEmployeeAssetRowsInternal(context),
    listPerformanceReviewsInternal(context),
    listOvertimeRequests(),
    listReportExportsInternal(context),
  ]);
  const previousPayroll = await getPreviousPayrollEmployeeRows(
    context,
    safeString((latestPayroll.run as Record<string, unknown> | null)?.id)
  );

  const totalEmployees = employees.length;
  const activeEmployees = employees.filter((row) => safeString(row.status).toLowerCase() === "active").length;
  const currentMonthPrefix = new Date().toISOString().slice(0, 7);
  const newHiresThisMonth = employees.filter((row) => safeString(row.hire_date).startsWith(currentMonthPrefix)).length;
  const exitsThisMonth = employees.filter((row) => safeString(row.status).toLowerCase() !== "active" && safeString(row.contract_end_date).startsWith(currentMonthPrefix)).length;
  const turnoverRate = totalEmployees ? Number(((exitsThisMonth / totalEmployees) * 100).toFixed(1)) : 0;
  const attendanceRate = attendanceDashboard.presentToday + attendanceDashboard.absentToday + attendanceDashboard.lateToday > 0
    ? Number((((attendanceDashboard.presentToday + attendanceDashboard.lateToday) / (attendanceDashboard.presentToday + attendanceDashboard.absentToday + attendanceDashboard.lateToday)) * 100).toFixed(1))
    : 100;
  const leaveUtilization = totalEmployees ? Number(((leaveDashboard.requestCount / totalEmployees) * 100).toFixed(1)) : 0;
  const employerStatutoryCost = latestPayroll.run
    ? safeNumber((latestPayroll.run as Record<string, unknown>).nssf_total) +
      safeNumber((latestPayroll.run as Record<string, unknown>).housing_levy_total) +
      safeNumber((latestPayroll.run as Record<string, unknown>).pension_total)
    : 0;
  const payrollByDepartment = countByLabel(
    latestPayroll.rows.map((row) => safeString((asRecord(row.employee)?.department as Record<string, unknown> | null)?.name, "Unassigned"))
  );
  const payrollByBranch = countByLabel(
    latestPayroll.rows.map((row) => safeString((asRecord(row.employee)?.branch as Record<string, unknown> | null)?.name, "Unassigned"))
  );
  const headcountByDepartment = countByLabel(employees.map((row) => safeString((row.department as Record<string, unknown> | null)?.name, "Unassigned")));
  const headcountByBranch = countByLabel(employees.map((row) => safeString((row.branch as Record<string, unknown> | null)?.name, "Unassigned")));
  const genderDistribution = countByLabel(employees.map((row) => safeString(row.gender, "Unknown")));
  const ageDistribution = countByLabel(employees.map((row) => buildAgeBracket(safeString(row.date_of_birth))));
  const trainingCompletionRate = training.length ? Number(((training.filter((row) => safeString(row.status) === "approved").length / training.length) * 100).toFixed(1)) : 0;
  const performanceDistribution = countByLabel(
    appraisals.map((row) => {
      const score = safeNumber(row.score);
      return buildPerformanceBand(score);
    })
  );
  const payrollTrend = recentRuns
    .slice()
    .reverse()
    .map((row) => ({
      label: safeString(row.period_label),
      grossPay: formatCurrency(safeNumber(row.gross_pay)),
      netPay: formatCurrency(safeNumber(row.net_pay)),
      employerCost: formatCurrency(safeNumber(row.employer_cost)),
    }));
  const leaveTrend = countByLabel(leaveDashboard.requestCount ? (await listLeaveRequests()).map((row) => safeString(row.leave_type)) : []);
  const overtimeTrend = countByLabel(overtimeRequests.map((row) => safeString(row.work_date).slice(0, 7)));
  const attendanceTrend = [
    { label: "Present", value: attendanceDashboard.presentToday },
    { label: "Absent", value: attendanceDashboard.absentToday },
    { label: "Late", value: attendanceDashboard.lateToday },
    { label: "On Leave", value: attendanceDashboard.onLeaveToday },
  ];
  const absenteeismRate =
    attendanceDashboard.presentToday + attendanceDashboard.absentToday + attendanceDashboard.lateToday > 0
      ? Number(((attendanceDashboard.absentToday / (attendanceDashboard.presentToday + attendanceDashboard.absentToday + attendanceDashboard.lateToday)) * 100).toFixed(1))
      : 0;
  const overtimeCost = overtimeRequests.reduce((sum, row) => sum + safeNumber(row.hours) * 500, 0);
  const payrollAnomalies = buildPayrollAnomalySummary({
    currentRows: latestPayroll.rows,
    previousRows: previousPayroll.rows,
  });
  const previousGrossPay = safeNumber(previousPayroll.run?.gross_pay);
  const previousNetPay = safeNumber(previousPayroll.run?.net_pay);
  const previousEmployerCost = safeNumber(previousPayroll.run?.employer_cost);
  const previousOvertimeCost = 0;
  const payrollComparison = {
    grossPay: {
      current: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).gross_pay)) : "KES 0",
      previous: previousPayroll.run ? formatCurrency(previousGrossPay) : "KES 0",
      movement: buildTrendLabel(
        latestPayroll.run ? safeNumber((latestPayroll.run as Record<string, unknown>).gross_pay) : 0,
        previousGrossPay,
        "gross pay",
        "currency"
      ),
    },
    netPay: {
      current: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).net_pay)) : "KES 0",
      previous: previousPayroll.run ? formatCurrency(previousNetPay) : "KES 0",
      movement: buildTrendLabel(
        latestPayroll.run ? safeNumber((latestPayroll.run as Record<string, unknown>).net_pay) : 0,
        previousNetPay,
        "net pay",
        "currency"
      ),
    },
    employerCost: {
      current: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).employer_cost)) : "KES 0",
      previous: previousPayroll.run ? formatCurrency(previousEmployerCost) : "KES 0",
      movement: buildTrendLabel(
        latestPayroll.run ? safeNumber((latestPayroll.run as Record<string, unknown>).employer_cost) : 0,
        previousEmployerCost,
        "employer cost",
        "currency"
      ),
    },
    overtime: {
      current: formatCurrency(overtimeCost),
      previous: formatCurrency(previousOvertimeCost),
      movement: buildTrendLabel(overtimeCost, previousOvertimeCost, "overtime cost", "currency"),
    },
  };

  let salaryRequestQuery = context.supabase
    .from("approval_tasks")
    .select("status, metadata")
    .eq("entity_type", "salary_change_request");
  let complaintQuery = context.supabase
    .from("approval_tasks")
    .select("status, metadata")
    .eq("entity_type", "staff_complaint");

  if (context.profile.company_id) {
    salaryRequestQuery = salaryRequestQuery.eq("company_id", context.profile.company_id);
    complaintQuery = complaintQuery.eq("company_id", context.profile.company_id);
  }

  const [{ data: salaryRequestRows, error: salaryRequestError }, { data: complaintRows, error: complaintError }] = await Promise.all([
    salaryRequestQuery,
    complaintQuery,
  ]);
  if (salaryRequestError) throw salaryRequestError;
  if (complaintError) throw complaintError;

  const salaryRequests = ((salaryRequestRows ?? []) as Array<Record<string, unknown>>).map((row) => ({
    status: safeString(row.status),
    metadata: asRecord(row.metadata),
  }));
  const approvedSalaryDelta = salaryRequests
    .filter((row) => safeString(row.status).toLowerCase() === "approved")
    .reduce((sum, row) => {
      const currentSalary = safeNumber(row.metadata?.currentSalary);
      const proposedSalary = safeNumber(row.metadata?.proposedSalary);
      return sum + Math.max(proposedSalary - currentSalary, 0);
    }, 0);
  const pendingSalaryDelta = salaryRequests
    .filter((row) => safeString(row.status).toLowerCase() === "pending")
    .reduce((sum, row) => {
      const currentSalary = safeNumber(row.metadata?.currentSalary);
      const proposedSalary = safeNumber(row.metadata?.proposedSalary);
      return sum + Math.max(proposedSalary - currentSalary, 0);
    }, 0);
  const payrollForecast = buildForecastSummary({
    recentRuns,
    approvedSalaryDelta,
    pendingSalaryDelta,
    overtimeCost,
  });

  const missingDataRows = employees.filter(
    (row) =>
      !safeString(row.kra_pin) ||
      !safeString(row.shif_number) ||
      !safeString(row.nssf_number) ||
      !safeString(row.bank_account)
  );
  const missingDataSummary = [
    { label: "Missing KRA PIN", value: employees.filter((row) => !safeString(row.kra_pin)).length },
    { label: "Missing SHIF", value: employees.filter((row) => !safeString(row.shif_number)).length },
    { label: "Missing NSSF", value: employees.filter((row) => !safeString(row.nssf_number)).length },
    { label: "Missing bank", value: employees.filter((row) => !safeString(row.bank_account)).length },
  ];
  const unresolvedComplaints = ((complaintRows ?? []) as Array<Record<string, unknown>>).filter(
    (row) => safeString(row.status).toLowerCase() !== "resolved" && safeString(row.status).toLowerCase() !== "approved"
  );
  const failedExports = exports.filter((row) => safeString(row.status).toLowerCase() === "failed");
  const performanceGroups = buildTopBottomPerformanceGroups(appraisals);
  const topPerformers = appraisals
    .map((row) => {
      const employee = asRecord(row.employee);
      const performance = derivePerformanceSnapshot(row);
      return {
        label: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim() || safeString(employee?.employee_number, "Employee"),
        value: performance.achievementPercent || safeNumber(row.score),
        display: `${performance.metricLabel} · ${performance.achievementPercent || safeNumber(row.score)}%`,
      };
    })
    .sort((left, right) => safeNumber(right.value) - safeNumber(left.value))
    .slice(0, 5);
  const strugglingPerformers = [...topPerformers].reverse().slice(0, 5);
  const supervisorPerformance = appraisals
    .map((row) => {
      const performance = derivePerformanceSnapshot(row);
      const employee = asRecord(row.employee);
      if (safeString(performance.subjectRole).toLowerCase() !== "supervisor") {
        return null;
      }
      return {
        label: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim() || safeString(employee?.employee_number, "Supervisor"),
        value: performance.achievementPercent,
        display: `${performance.weekLabel} · ${performance.achievementPercent}% · ${safeString(performance.managerRating, "No GM rating")}`,
      };
    })
    .filter((value): value is { label: string; value: number; display: string } => Boolean(value))
    .sort((left, right) => safeNumber(right.value) - safeNumber(left.value))
    .slice(0, 6);

  const insightsFeed = buildExecutiveInsights({
    currentGross: latestPayroll.run ? safeNumber((latestPayroll.run as Record<string, unknown>).gross_pay) : 0,
    previousGross: previousGrossPay,
    currentNet: latestPayroll.run ? safeNumber((latestPayroll.run as Record<string, unknown>).net_pay) : 0,
    previousNet: previousNetPay,
    pendingApprovals: approvalTasks.filter((task) => task.status === "pending").length,
    missingDataCount: missingDataRows.length,
    anomalies: payrollAnomalies,
    reviews: appraisals,
    overtimeCost,
  });

  await logReportAccess(context, {
    moduleKey: "reports",
    category: "Executive Dashboard",
    reportName: "Executive Dashboard",
    reportKey: "executive_dashboard",
    action: "run",
  });

  return {
    metrics: {
      totalEmployees,
      activeEmployees,
      newHiresThisMonth,
      exitsThisMonth,
      totalMonthlyPayrollCost: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).employer_cost)) : "KES 0",
      totalGrossPay: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).gross_pay)) : "KES 0",
      totalNetPay: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).net_pay)) : "KES 0",
      employerStatutoryCost: formatCurrency(employerStatutoryCost),
      shifTotal: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).shif_total)) : "KES 0",
      nssfTotal: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).nssf_total)) : "KES 0",
      housingLevyTotal: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).housing_levy_total)) : "KES 0",
      payeTotal: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).paye_total)) : "KES 0",
      overtimeTotal: formatCurrency(overtimeCost),
      bonusTotal: formatCurrency(
        latestPayroll.rows.reduce(
          (sum, row) =>
            sum +
            getPayrollRowAmount((row.allowances as Record<string, unknown> | null) ?? {}, ["Bonus", "bonus"]),
          0
        )
      ),
      incentiveTotal: formatCurrency(
        latestPayroll.rows.reduce(
          (sum, row) =>
            sum +
            getPayrollRowAmount((row.allowances as Record<string, unknown> | null) ?? {}, [
              "Incentives",
              "Incentive",
              "incentives",
            ]),
          0
        )
      ),
      leaveUtilization,
      attendanceRate,
      turnoverRate,
      absenteeismRate,
      pendingApprovals: approvalTasks.filter((task) => task.status === "pending").length,
      recruitmentPipeline: requisitions.length,
      trainingCompletionRate,
      assetAllocationSummary: assets.filter((row) => safeString(row.status) === "assigned").length,
      projectedNextMonthPayroll: payrollForecast.nextMonthWagebill,
      projectedAnnualPayroll: payrollForecast.projectedAnnualPayroll,
      unresolvedComplaints: unresolvedComplaints.length,
      missingEmployeeData: missingDataRows.length,
      failedExports: failedExports.length,
      payrollWarnings: payrollAnomalies.length,
    },
    charts: {
      payrollTrend,
      headcountByDepartment,
      headcountByBranch,
      leaveTrend,
      overtimeTrend,
      attendanceTrend,
      payrollByDepartment,
      payrollByBranch,
      genderDistribution,
      ageDistribution,
      performanceDistribution,
      topTeams: performanceGroups.topTeams,
      underperformingTeams: performanceGroups.underperformingTeams,
      topPerformers,
      strugglingPerformers,
      supervisorPerformance,
    },
    payrollIntelligence: {
      anomalies: payrollAnomalies,
      comparison: payrollComparison,
      forecast: payrollForecast,
      departmentCostComparison: payrollByDepartment,
      branchCostComparison: payrollByBranch,
    },
    workforceIntelligence: {
      activeStaff: activeEmployees,
      newHires: newHiresThisMonth,
      exits: exitsThisMonth,
      absenteeismRate,
      missingDataSummary,
    },
    performanceIntelligence: {
      topTeams: performanceGroups.topTeams,
      underperformingTeams: performanceGroups.underperformingTeams,
      topPerformers,
      strugglingPerformers,
      supervisorPerformance,
    },
    financeIntelligence: {
      deductionsTrend: payrollComparison,
      statutoryLiabilitySummary: [
        { label: "PAYE", value: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).paye_total)) : "KES 0" },
        { label: "SHIF", value: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).shif_total)) : "KES 0" },
        { label: "NSSF", value: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).nssf_total)) : "KES 0" },
        { label: "Housing Levy", value: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).housing_levy_total)) : "KES 0" },
      ],
      projectedPayrollNextMonth: payrollForecast.nextMonthWagebill,
    },
    operationsHealth: {
      cards: {
        pendingApprovals: approvalTasks.filter((task) => task.status === "pending").length,
        unresolvedComplaints: unresolvedComplaints.length,
        failedExports: failedExports.length,
        missingEmployeeData: missingDataRows.length,
        payrollWarnings: payrollAnomalies.length,
        overdueTasks: approvalTasks.filter((task) => task.status === "pending").slice(0, 5).length,
      },
      warnings: [
        ...failedExports.slice(0, 5).map((row) => ({
          title: safeString(row.report_name, "Failed export"),
          detail: `${safeString(row.category, "Reports")} export failed on ${safeString(row.created_at, "recent run")}.`,
          tone: "critical",
        })),
        ...missingDataRows.slice(0, 5).map((row) => ({
          title: titleFromEmployee(row),
          detail: "Employee record is missing statutory or bank data needed for clean payroll operations.",
          tone: "warning",
        })),
      ],
      missingData: missingDataRows.slice(0, 8).map((row) => ({
        label: titleFromEmployee(row),
        value: [
          !safeString(row.kra_pin) ? "KRA PIN" : "",
          !safeString(row.shif_number) ? "SHIF" : "",
          !safeString(row.nssf_number) ? "NSSF" : "",
          !safeString(row.bank_account) ? "Bank" : "",
        ]
          .filter(Boolean)
          .join(", "),
      })),
      reminders: [
        {
          title: "Payroll close checklist",
          detail: latestPayroll.run ? `Latest payroll period is ${safeString((latestPayroll.run as Record<string, unknown>).period_label)}. Queue board-ready reports right after approval.` : "No payroll run is active yet.",
          status: latestPayroll.run ? safeString((latestPayroll.run as Record<string, unknown>).status, "Draft") : "Pending setup",
        },
        {
          title: "Automatic payslip publishing",
          detail: "Picks up right after payroll approval and release.",
          status: latestPayroll.run && safeString((latestPayroll.run as Record<string, unknown>).status) === "Approved" ? "Ready" : "Waiting for approval",
        },
        {
          title: "Scheduled report generation",
          detail: `${exports.length} export artifact(s) already logged for this tenant.`,
          status: failedExports.length ? "Warnings present" : "Healthy",
        },
      ],
    },
    automationCenter: {
      reminders: [
        { title: "Payroll approval reminder", audience: "Payroll Admin / GM", trigger: "Pending approval state", status: approvalTasks.filter((task) => task.status === "pending").length ? "Action due" : "Clear" },
        { title: "Missing profile reminder", audience: "Employees", trigger: `${missingDataRows.length} records missing payroll-critical fields`, status: missingDataRows.length ? "Needs follow-up" : "Clear" },
        { title: "Incomplete document reminder", audience: "Employees / HR", trigger: "Compliance gaps and missing employee docs", status: missingDataRows.length ? "Watchlist" : "Clear" },
      ],
      workflows: [
        { title: "Monthly payroll close checklist", status: "Live", detail: "Use after payroll approval to release payslips, reports, and exports." },
        { title: "Automatic payslip publishing", status: "Live", detail: "Picks up approved payroll runs and makes the latest slip visible in ESS." },
        { title: "Automatic report generation", status: "Ready", detail: "Scheduled reports can now ride the same executive/reporting center." },
      ],
    },
    insightsFeed,
  };
}

async function fetchApprovalTasksInternal(context: RequestContext) {
  let query = context.supabase
    .from("approval_tasks")
    .select("id, module_key, entity_type, title, description, owner_role, status, stage, updated_at, metadata, requester:requested_by(email, role)")
    .order("updated_at", { ascending: false })
    .limit(100);

  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }

  if (context.profile.role === "Supervisor") {
    query = query.eq("owner_role", context.profile.role);
  }

  const { data, error } = await query;
  if (error) throw error;
  const rows = (data ?? []) as TaskRow[];

  if (context.profile.role === "Manager") {
    const mapped = rows
      .filter((row) => {
        const metadata = asRecord(row.metadata);
        const allowedApproverRoles = Array.isArray(metadata?.allowed_approver_roles)
          ? metadata.allowed_approver_roles.map((value) => safeString(value))
          : [];
        return safeString(row.owner_role) === "Manager" || allowedApproverRoles.includes("Manager");
      })
      .map((row) => mapApprovalTask(row));
    const supplemental = await listSupplementalPerformanceApprovalTasks(context);
    return sortApprovalTasksByRecency([...mapped, ...supplemental]);
  }

  if (context.profile.role === "Supervisor" && context.profile.employee_id) {
    const scopedEmployeeIds = new Set((await getScopedEmployeeIds(context)) ?? []);
    const mapped = rows
      .filter((row) => {
        if (safeString(row.entity_type) !== "staff_complaint") {
          return true;
        }

        const metadata = asRecord(row.metadata);
        return scopedEmployeeIds.has(safeString(metadata?.employeeId));
      })
      .map((row) => mapApprovalTask(row));
    const supplemental = await listSupplementalPerformanceApprovalTasks(context);
    return sortApprovalTasksByRecency([...mapped, ...supplemental]);
  }

  const mapped = rows.map((row) => mapApprovalTask(row));
  const supplemental = await listSupplementalPerformanceApprovalTasks(context);
  return sortApprovalTasksByRecency([...mapped, ...supplemental]);
}

async function listRecruitmentRequisitionsInternal(context: RequestContext) {
  let query = context.supabase
    .from("recruitment_requisitions")
    .select("id, role_title, status, headcount, created_at, department:departments(name), branch:branches(name)")
    .order("created_at", { ascending: false })
    .limit(100);
  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }
  const { data, error } = await query;
  if (error) throw error;
  return (data ?? []) as Array<Record<string, unknown>>;
}

async function listTrainingRequestsInternal(context: RequestContext) {
  const scopedEmployeeIds = await getScopedEmployeeIds(context);
  let query = context.supabase
    .from("training_requests")
    .select("id, employee_id, program_name, schedule, budget, status, created_at, employee:employee_id(employee_number, first_name, last_name, department:department_id(name))")
    .order("created_at", { ascending: false })
    .limit(200);
  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }
  query = applyScopedEmployeeIds(query as never, scopedEmployeeIds) as typeof query;
  const { data, error } = await query;
  if (error) throw error;
  return (data ?? []) as Array<Record<string, unknown>>;
}

