function derivePerformanceIndicator(achievementPercent: number) {
  if (achievementPercent >= 100) {
    return "green";
  }

  if (achievementPercent >= 70) {
    return "amber";
  }

  return "red";
}

function derivePerformanceSnapshot(review: Record<string, unknown>) {
  const kpis = Array.isArray(review.kpis)
    ? review.kpis.filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object" && !Array.isArray(item)
      )
    : [];
  const primary = kpis[0] ?? {};
  const targetValue = safeNumber(primary.targetValue ?? primary.target ?? primary.weeklyTarget);
  const actualValue = safeNumber(primary.actualValue ?? primary.actual ?? primary.weeklyActual);
  const achievementPercent =
    targetValue > 0
      ? Number(((actualValue / targetValue) * 100).toFixed(2))
      : safeNumber(primary.achievementPercent);
  const indicator = safeString(primary.indicator) || derivePerformanceIndicator(achievementPercent);

  return {
    metricLabel: safeString(primary.metricLabel, safeString(review.review_cycle, "Weekly target")),
    subjectRole: safeString(primary.subjectRole),
    targetValue,
    actualValue,
    achievementPercent,
    indicator,
    weekLabel: safeString(primary.weekLabel, safeString(review.review_period)),
    managerRating: safeString(primary.managerRating),
  };
}

async function listPayrollTrendInternal(context: RequestContext) {
  let query = context.supabase
    .from("payroll_runs")
    .select("period_label, gross_pay, net_pay, employer_cost, processed_at")
    .order("created_at", { ascending: false })
    .limit(6);
  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }
  const { data, error } = await query;
  if (error) throw error;
  return ((data ?? []) as Array<Record<string, unknown>>)
    .reverse()
    .map((row) => ({
      label: safeString(row.period_label),
      grossPay: formatCurrency(safeNumber(row.gross_pay)),
      netPay: formatCurrency(safeNumber(row.net_pay)),
      employerCost: formatCurrency(safeNumber(row.employer_cost)),
    }));
}

