export async function getPayrollReportsSnapshot() {
  const context = await getRequestContext();
  ensureReportCategoryAccess(context.profile, "payroll");
  const latestPayroll = await getLatestPayrollEmployeeRows(context);
  const summary = await getStatutorySummary();
  const exports = await listReportExportsInternal(context);

  await logReportAccess(context, {
    moduleKey: "reports",
    category: "Payroll Reports",
    reportName: "Payroll Reports",
    reportKey: "payroll_reports",
    action: "run",
  });

  return {
    latestPeriod: safeString((latestPayroll.run as Record<string, unknown> | null)?.period_label, "No payroll run"),
    cards: {
      grossPay: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).gross_pay)) : "KES 0",
      netPay: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).net_pay)) : "KES 0",
      employerCost: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).employer_cost)) : "KES 0",
      employees: latestPayroll.rows.length,
    },
    register: latestPayroll.rows.map((row) => {
      const employee = asRecord(row.employee);
      const rawDeductions = row.deductions && typeof row.deductions === "object" ? (row.deductions as Record<string, unknown>) : {};
      return {
        employeeNumber: safeString(employee?.employee_number),
        employeeName: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        department: safeString((employee?.department as Record<string, unknown> | null)?.name, "-"),
        branch: safeString((employee?.branch as Record<string, unknown> | null)?.name, "-"),
        grossPay: formatCurrency(safeNumber(row.gross_pay)),
        netPay: formatCurrency(safeNumber(row.net_pay)),
        totalDeductions: formatCurrency(Object.values(rawDeductions).reduce<number>((sum, value) => sum + safeNumber(value), 0)),
      };
    }),
    statutorySummary: summary,
    wageBillSummary: {
      grossPay: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).gross_pay)) : "KES 0",
      totalDeductions: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).total_deductions)) : "KES 0",
      netPay: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).net_pay)) : "KES 0",
    },
    employerCostSummary: {
      employerCost: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).employer_cost)) : "KES 0",
      nssf: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).nssf_total)) : "KES 0",
      housingLevy: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).housing_levy_total)) : "KES 0",
      pension: latestPayroll.run ? formatCurrency(safeNumber((latestPayroll.run as Record<string, unknown>).pension_total)) : "KES 0",
    },
    deductionSummary: countByLabel(
      latestPayroll.rows.flatMap((row) =>
        Object.keys((row.deductions as Record<string, unknown> | null) ?? {}).map((key) => key)
      )
    ),
    loanBalances: latestPayroll.rows
      .map((row) => {
        const employee = asRecord(row.employee);
        const deductions = (row.deductions as Record<string, unknown> | null) ?? {};
        return {
          employeeNumber: safeString(employee?.employee_number),
          employeeName: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
          loanDeduction: formatCurrency(getJsonAmount(deductions, ["Loans", "loan", "loans"])),
          saccoDeduction: formatCurrency(getJsonAmount(deductions, ["SACCO", "sacco"])),
        };
      })
      .filter((row) => row.loanDeduction !== "KES 0" || row.saccoDeduction !== "KES 0"),
    overtimeReport: latestPayroll.rows
      .map((row) => {
        const employee = asRecord(row.employee);
        const allowances = (row.allowances as Record<string, unknown> | null) ?? {};
        return {
          employeeNumber: safeString(employee?.employee_number),
          employeeName: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
          overtime: formatCurrency(getJsonAmount(allowances, ["Overtime", "overtime"])),
        };
      })
      .filter((row) => row.overtime !== "KES 0"),
    byDepartment: countByLabel(latestPayroll.rows.map((row) => safeString((asRecord(row.employee)?.department as Record<string, unknown> | null)?.name, "Unassigned"))),
    byBranch: countByLabel(latestPayroll.rows.map((row) => safeString((asRecord(row.employee)?.branch as Record<string, unknown> | null)?.name, "Unassigned"))),
    payrollVariance: await getPayrollVariance(),
    exportHistory: exports.filter((item) => safeString(item.category) === "Payroll Reports"),
  };
}

