export async function getComplianceReportsSnapshot() {
  const context = await getRequestContext();
  ensureReportCategoryAccess(context.profile, "compliance");
  const employees = await getScopedEmployeeDetailRows(context);
  let documentsQuery = context.supabase
    .from("employee_documents")
    .select("employee_id, category");

  if (context.profile.company_id) {
    documentsQuery = documentsQuery.eq("company_id", context.profile.company_id);
  }

  const { data: documents, error: documentsError } = await documentsQuery;
  if (documentsError) {
    throw documentsError;
  }

  const documentRows = (documents ?? []) as Array<Record<string, unknown>>;
  const employeesWithDocuments = new Set(documentRows.map((row) => safeString(row.employee_id)).filter(Boolean));

  await logReportAccess(context, {
    moduleKey: "reports",
    category: "Compliance Reports",
    reportName: "Compliance Reports",
    reportKey: "compliance_reports",
    action: "run",
  });

  const gaps = employees.map((row) => ({
    employeeNumber: safeString(row.employee_number),
    fullName: titleFromEmployee(row),
    missingKraPin: !safeString(row.kra_pin),
    missingShif: !safeString(row.shif_number),
    missingNssf: !safeString(row.nssf_number),
    missingBank: !safeString(row.bank_account),
    missingContract: safeString(row.contract_end_date) === "",
  }));

  return {
    cards: {
      missingKraPin: gaps.filter((row) => row.missingKraPin).length,
      missingShif: gaps.filter((row) => row.missingShif).length,
      missingNssf: gaps.filter((row) => row.missingNssf).length,
      missingBank: gaps.filter((row) => row.missingBank).length,
      documentCount: documentRows.length,
      employeesMissingDocuments: employees.filter((row) => !employeesWithDocuments.has(safeString(row.id))).length,
    },
    gaps,
  };
}

export async function getBranchReportsSnapshot() {
  const context = await getRequestContext();
  ensureReportCategoryAccess(context.profile, "branch");
  const [employees, payroll, leave, attendance] = await Promise.all([
    getScopedEmployeeDetailRows(context),
    getLatestPayrollEmployeeRows(context),
    listLeaveRequests(),
    listAttendanceRecords(),
  ]);

  await logReportAccess(context, {
    moduleKey: "reports",
    category: "Branch Reports",
    reportName: "Branch Reports",
    reportKey: "branch_reports",
    action: "run",
  });

  const branchMap = new Map<string, { branch: string; headcount: number; leaveRequests: number; attendanceExceptions: number; payrollEmployees: number }>();
  for (const employee of employees) {
    const branch = safeString((employee.branch as Record<string, unknown> | null)?.name, "Unassigned");
    if (!branchMap.has(branch)) branchMap.set(branch, { branch, headcount: 0, leaveRequests: 0, attendanceExceptions: 0, payrollEmployees: 0 });
    branchMap.get(branch)!.headcount += 1;
  }
  for (const row of leave) {
    const employee = asRecord(row.employee);
    const branch = safeString((employee?.branch as Record<string, unknown> | null)?.name, "Unassigned");
    if (!branchMap.has(branch)) branchMap.set(branch, { branch, headcount: 0, leaveRequests: 0, attendanceExceptions: 0, payrollEmployees: 0 });
    branchMap.get(branch)!.leaveRequests += 1;
  }
  for (const row of attendance) {
    const employee = asRecord(row.employee);
    const branch = safeString((employee?.branch as Record<string, unknown> | null)?.name, "Unassigned");
    if (!branchMap.has(branch)) branchMap.set(branch, { branch, headcount: 0, leaveRequests: 0, attendanceExceptions: 0, payrollEmployees: 0 });
    if (["absent", "late", "incomplete"].includes(safeString(row.status))) branchMap.get(branch)!.attendanceExceptions += 1;
  }
  for (const row of payroll.rows) {
    const employee = asRecord(row.employee);
    const branch = safeString((employee?.branch as Record<string, unknown> | null)?.name, "Unassigned");
    if (!branchMap.has(branch)) branchMap.set(branch, { branch, headcount: 0, leaveRequests: 0, attendanceExceptions: 0, payrollEmployees: 0 });
    branchMap.get(branch)!.payrollEmployees += 1;
  }
  return Array.from(branchMap.values());
}

export async function getDepartmentReportsSnapshot() {
  const context = await getRequestContext();
  ensureReportCategoryAccess(context.profile, "department");
  const [employees, payroll, leave, training] = await Promise.all([
    getScopedEmployeeDetailRows(context),
    getLatestPayrollEmployeeRows(context),
    listLeaveRequests(),
    listTrainingRequestsInternal(context),
  ]);

  await logReportAccess(context, {
    moduleKey: "reports",
    category: "Department Reports",
    reportName: "Department Reports",
    reportKey: "department_reports",
    action: "run",
  });

  const departmentMap = new Map<string, { department: string; headcount: number; leaveRequests: number; payrollEmployees: number; trainingRequests: number }>();
  for (const employee of employees) {
    const department = safeString((employee.department as Record<string, unknown> | null)?.name, "Unassigned");
    if (!departmentMap.has(department)) departmentMap.set(department, { department, headcount: 0, leaveRequests: 0, payrollEmployees: 0, trainingRequests: 0 });
    departmentMap.get(department)!.headcount += 1;
  }
  for (const row of leave) {
    const employee = asRecord(row.employee);
    const department = safeString((employee?.department as Record<string, unknown> | null)?.name, "Unassigned");
    if (!departmentMap.has(department)) departmentMap.set(department, { department, headcount: 0, leaveRequests: 0, payrollEmployees: 0, trainingRequests: 0 });
    departmentMap.get(department)!.leaveRequests += 1;
  }
  for (const row of payroll.rows) {
    const employee = asRecord(row.employee);
    const department = safeString((employee?.department as Record<string, unknown> | null)?.name, "Unassigned");
    if (!departmentMap.has(department)) departmentMap.set(department, { department, headcount: 0, leaveRequests: 0, payrollEmployees: 0, trainingRequests: 0 });
    departmentMap.get(department)!.payrollEmployees += 1;
  }
  for (const row of training) {
    const employee = asRecord(row.employee);
    const department = safeString((employee?.department as Record<string, unknown> | null)?.name, "Unassigned");
    if (!departmentMap.has(department)) departmentMap.set(department, { department, headcount: 0, leaveRequests: 0, payrollEmployees: 0, trainingRequests: 0 });
    departmentMap.get(department)!.trainingRequests += 1;
  }
  return Array.from(departmentMap.values());
}

export async function getConsultancyReportsSnapshot() {
  const context = await getRequestContext();
  ensureReportCategoryAccess(context.profile, "consultancy");

  let companyQuery = context.supabase.from("companies").select("id, name, status").order("name", { ascending: true });
  if (context.profile.company_id && context.profile.role !== "Super Admin") {
    companyQuery = companyQuery.eq("id", context.profile.company_id);
  }
  const { data: companies, error } = await companyQuery;
  if (error) throw error;

  const companyRows = (companies ?? []) as Array<Record<string, unknown>>;
  const summary: Array<Record<string, unknown>> = [];
  for (const company of companyRows) {
    const companyId = safeString(company.id);
    const [{ count: employees }, { data: payroll }, { count: leaveRequests }, { count: approvals }] = await Promise.all([
      context.supabase.from("employees").select("id", { count: "exact", head: true }).eq("company_id", companyId),
      context.supabase.from("payroll_runs").select("gross_pay, validation_errors").eq("company_id", companyId).order("created_at", { ascending: false }).limit(1).maybeSingle(),
      context.supabase.from("leave_requests").select("id", { count: "exact", head: true }).eq("company_id", companyId),
      context.supabase.from("approval_tasks").select("id", { count: "exact", head: true }).eq("company_id", companyId).eq("status", "pending"),
    ]);
    summary.push({
      companyName: safeString(company.name),
      employees: employees ?? 0,
      grossPay: formatCurrency(safeNumber((payroll as Record<string, unknown> | null)?.gross_pay)),
      leaveRequests: leaveRequests ?? 0,
      pendingApprovals: approvals ?? 0,
      payrollErrors: safeNumber((payroll as Record<string, unknown> | null)?.validation_errors),
    });
  }

  await logReportAccess(context, {
    moduleKey: "reports",
    category: "Consultancy Reports",
    reportName: "Consultancy Reports",
    reportKey: "consultancy_reports",
    action: "run",
  });

  return {
    cards: {
      companies: companyRows.length,
      totalEmployees: summary.reduce((sum, row) => sum + safeNumber(row.employees), 0),
      pendingApprovals: summary.reduce((sum, row) => sum + safeNumber(row.pendingApprovals), 0),
      payrollErrors: summary.reduce((sum, row) => sum + safeNumber(row.payrollErrors), 0),
    },
    companies: summary,
  };
}

