export async function getPerformanceWorkspace() {
  const context = await getRequestContext();
  if (!roleCanAccessModule(context.profile.role, "performance")) {
    throw new Error("forbidden");
  }

  const reviews = await listPerformanceReviewsInternal(context);
  const employees =
    context.profile.role === "Employee" || !roleCanAccessPeople(context.profile.role)
      ? []
      : await listEmployeeRecords();

  const totalScore = reviews.reduce((sum, row) => sum + safeNumber(row.score), 0);

  return {
    viewerRole: context.profile.role,
    summary: {
      totalReviews: reviews.length,
      completedReviews: reviews.filter((row) => safeString(row.status) === "completed").length,
      activePips: reviews.filter((row) => safeString(row.pip_status).length > 0 && safeString(row.pip_status) !== "none").length,
      promotionCases: reviews.filter((row) => safeString(row.promotion_recommendation).length > 0).length,
      averageScore: reviews.length ? Number((totalScore / reviews.length).toFixed(2)) : 0,
    },
    reviews: reviews.map((row) => {
      const employee = asRecord(row.employee);
      const performance = derivePerformanceSnapshot(row);
      return {
        id: safeString(row.id),
        employeeId: safeString(row.employee_id),
        employeeName: `${safeString(employee?.employee_number)} ${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        department: safeString((employee?.department as Record<string, unknown> | null)?.name, "Unassigned"),
        reviewCycle: safeString(row.review_cycle),
        reviewPeriod: safeString(row.review_period),
        score: safeNumber(row.score),
        status: safeString(row.status),
        supervisorComments: safeString(row.supervisor_comments),
        hrComments: safeString(row.hr_comments),
        promotionRecommendation: safeString(row.promotion_recommendation),
        pipStatus: safeString(row.pip_status),
        goals: Array.isArray(row.goals) ? row.goals : [],
        kpis: Array.isArray(row.kpis) ? row.kpis : [],
        metricLabel: performance.metricLabel,
        targetValue: performance.targetValue,
        actualValue: performance.actualValue,
        achievementPercent: performance.achievementPercent,
        indicator: performance.indicator,
        weekLabel: performance.weekLabel,
        managerRating: performance.managerRating,
        subjectRole: performance.subjectRole,
        createdAt: safeString(row.created_at),
      };
    }),
    employees: employees.map((employee) => ({
      id: employee.id,
      label: `${employee.employeeNumber} ${employee.fullName}`.trim(),
      department: employee.department,
      branch: employee.branch,
    })),
    canCreate:
      ["Super Admin", "HR Admin", "Manager", "Supervisor", "Employee"].includes(context.profile.role) &&
      Boolean(context.profile.employee_id || employees.length),
  };
}

export async function createPerformanceReview(input: {
  employeeId?: string | null;
  reviewCycle: string;
  reviewPeriod: string;
  score?: number;
  status?: string;
  supervisorComments?: string;
  hrComments?: string;
  promotionRecommendation?: string;
  pipStatus?: string;
  goals?: Array<Record<string, unknown>>;
  kpis?: Array<Record<string, unknown>>;
}) {
  const context = await getRequestContext();

  const role = context.profile.role;
  const targetEmployeeId =
    role === "Employee" ? context.profile.employee_id : input.employeeId ?? context.profile.employee_id;

  if (!targetEmployeeId) {
    throw new Error("missing_employee_id");
  }

  if (role === "Employee" && targetEmployeeId !== context.profile.employee_id) {
    throw new Error("forbidden");
  }

  if (role !== "Employee") {
    ensureRole(context.profile, ["Super Admin", "HR Admin", "Manager", "Supervisor"]);
    await assertEmployeeScope(context, targetEmployeeId);
  }

  const payload = {
    company_id: context.profile.company_id,
    employee_id: targetEmployeeId,
    review_cycle: input.reviewCycle,
    review_period: input.reviewPeriod,
    score: input.score ?? 0,
    status: input.status ?? (role === "Employee" ? "self_review" : "pending"),
    supervisor_comments: input.supervisorComments ?? null,
    hr_comments: ["Super Admin", "HR Admin", "Manager"].includes(role) ? input.hrComments ?? null : null,
    promotion_recommendation: input.promotionRecommendation ?? null,
    pip_status: input.pipStatus ?? null,
    goals: input.goals ?? [],
    kpis: input.kpis ?? [],
  };

  const { data, error } = await context.supabase
    .from("performance_reviews")
    .insert(payload)
    .select("*")
    .single();

  if (error || !data) {
    throw error ?? new Error("performance_review_create_failed");
  }

  await createAuditLog(context, {
    moduleKey: "performance",
    entityType: "performance_review",
    entityId: safeString(data.id),
    action: "create",
    afterValue: payload,
  });

  if (role !== "Employee") {
    await syncPerformanceApprovalTask(context, data as Record<string, unknown>);
  }

  return data;
}

export async function updatePerformanceReview(
  reviewId: string,
  input: {
    status?: string;
    score?: number;
    supervisorComments?: string;
    hrComments?: string;
    promotionRecommendation?: string;
    pipStatus?: string;
    goals?: Array<Record<string, unknown>>;
    kpis?: Array<Record<string, unknown>>;
  }
) {
  const context = await getRequestContext();
  const { data: before, error: fetchError } = await context.supabase
    .from("performance_reviews")
    .select("*")
    .eq("id", reviewId)
    .single();

  if (fetchError || !before) {
    throw fetchError ?? new Error("performance_review_not_found");
  }

  if (
    context.profile.role === "Employee" &&
    safeString((before as Record<string, unknown>).employee_id) !== safeString(context.profile.employee_id)
  ) {
    throw new Error("forbidden");
  }

  if (
    context.profile.role !== "Employee" &&
    !["Super Admin", "HR Admin", "Manager", "Supervisor"].includes(context.profile.role)
  ) {
    throw new Error("forbidden");
  }

  if (context.profile.role !== "Employee") {
    await assertEmployeeScope(context, safeString((before as Record<string, unknown>).employee_id));
  }

  const updates: Record<string, unknown> = {};
  if (input.status !== undefined) updates.status = input.status;

  if (context.profile.role === "Employee") {
    if (input.score !== undefined) updates.score = input.score;
  } else {
    if (input.score !== undefined) updates.score = input.score;
    if (input.supervisorComments !== undefined) updates.supervisor_comments = input.supervisorComments;
    if (input.goals !== undefined) updates.goals = input.goals;
    if (input.kpis !== undefined) updates.kpis = input.kpis;
  }

  if (["Super Admin", "HR Admin", "Manager"].includes(context.profile.role)) {
    if (input.hrComments !== undefined) updates.hr_comments = input.hrComments;
    if (input.promotionRecommendation !== undefined) updates.promotion_recommendation = input.promotionRecommendation;
    if (input.pipStatus !== undefined) updates.pip_status = input.pipStatus;
  }

  if (!Object.keys(updates).length) {
    return before;
  }

  const { data, error } = await context.supabase
    .from("performance_reviews")
    .update(updates)
    .eq("id", reviewId)
    .select("*")
    .single();

  if (error || !data) {
    throw error ?? new Error("performance_review_update_failed");
  }

  await createAuditLog(context, {
    moduleKey: "performance",
    entityType: "performance_review",
    entityId: reviewId,
    action: "update",
    beforeValue: before as Record<string, unknown>,
    afterValue: data as Record<string, unknown>,
  });

  if (context.profile.role !== "Employee") {
    await syncPerformanceApprovalTask(context, data as Record<string, unknown>);
  }

  return data;
}

