export async function getAssetsWorkspace() {
  const context = await getRequestContext();
  if (!roleCanAccessModule(context.profile.role, "assets")) {
    throw new Error("forbidden");
  }

  const scopedEmployeeIds = await getScopedEmployeeIds(context);
  const assignments = await listEmployeeAssetRowsInternal(context);

  let requestQuery = context.supabase
    .from("asset_requests")
    .select("id, employee_id, asset_name, request_type, status, created_at, notes, employee:employee_id(employee_number, first_name, last_name, branch:branch_id(name))")
    .order("created_at", { ascending: false })
    .limit(200);

  if (context.profile.company_id) {
    requestQuery = requestQuery.eq("company_id", context.profile.company_id);
  }

  requestQuery = applyScopedEmployeeIds(requestQuery as never, scopedEmployeeIds) as typeof requestQuery;

  const { data: requestRows, error: requestError } = await requestQuery;
  if (requestError) {
    throw requestError;
  }

  const employees =
    context.profile.role === "Employee" || !roleCanAccessPeople(context.profile.role)
      ? []
      : await listEmployeeRecords();

  const now = new Date().toISOString().slice(0, 10);

  return {
    summary: {
      totalAssignments: assignments.length,
      activeAssignments: assignments.filter((row) => safeString(row.status) === "assigned").length,
      overdueReturns: assignments.filter(
        (row) =>
          safeString(row.expected_return_date).length > 0 &&
          safeString(row.expected_return_date) < now &&
          safeString(row.status) !== "returned"
      ).length,
      pendingRequests: (requestRows ?? []).filter((row) => safeString((row as Record<string, unknown>).status) === "pending").length,
    },
    assignments: assignments.map((row) => {
      const employee = asRecord(row.employee);
      return {
        id: safeString(row.id),
        employeeName: `${safeString(employee?.employee_number)} ${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        department: safeString((employee?.department as Record<string, unknown> | null)?.name, "Unassigned"),
        branch: safeString((employee?.branch as Record<string, unknown> | null)?.name, "Unassigned"),
        assetName: safeString(row.asset_name),
        assetCategory: safeString(row.asset_category),
        serialNumber: safeString(row.serial_number),
        status: safeString(row.status),
        issueDate: safeString(row.issue_date),
        expectedReturnDate: safeString(row.expected_return_date),
      };
    }),
    requests: ((requestRows ?? []) as Array<Record<string, unknown>>).map((row) => {
      const employee = asRecord(row.employee);
      return {
        id: safeString(row.id),
        employeeName: `${safeString(employee?.employee_number)} ${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        branch: safeString((employee?.branch as Record<string, unknown> | null)?.name, "Unassigned"),
        assetName: safeString(row.asset_name),
        requestType: safeString(row.request_type),
        status: safeString(row.status),
        createdAt: safeString(row.created_at),
        notes: safeString(row.notes),
      };
    }),
    employees: employees.map((employee) => ({
      id: employee.id,
      label: `${employee.employeeNumber} ${employee.fullName}`.trim(),
      department: employee.department,
      branch: employee.branch,
    })),
    canAssign: ["Super Admin", "HR Admin", "Operator", "Supervisor"].includes(context.profile.role),
    canRequest: Boolean(context.profile.employee_id),
  };
}

