export async function getIntegrationsWorkspace() {
  const context = await getRequestContext();
  if (!roleCanAccessModule(context.profile.role, "integrations")) {
    throw new Error("forbidden");
  }

  let payrollRunQuery = context.supabase
    .from("payroll_runs")
    .select("period_label, status, paye_total, shif_total, nssf_total, housing_levy_total, processed_at")
    .order("created_at", { ascending: false })
    .limit(1);

  let exportQuery = context.supabase
    .from("payroll_exports")
    .select("id, export_type, status, file_name, created_at")
    .order("created_at", { ascending: false })
    .limit(12);

  let bankCoverageQuery = context.supabase
    .from("employees")
    .select("id, bank_name, bank_account")
    .limit(400);

  let notificationQuery = context.supabase
    .from("notification_settings")
    .select("email_enabled, in_app_enabled, sms_enabled")
    .limit(1);

  if (context.profile.company_id) {
    payrollRunQuery = payrollRunQuery.eq("company_id", context.profile.company_id);
    exportQuery = exportQuery.eq("company_id", context.profile.company_id);
    bankCoverageQuery = bankCoverageQuery.eq("company_id", context.profile.company_id);
    notificationQuery = notificationQuery.eq("company_id", context.profile.company_id);
  }

  const [{ data: payrollRun }, { data: exportRows }, { data: employees }, devices, { data: notificationSettings }] =
    await Promise.all([
      payrollRunQuery.maybeSingle(),
      exportQuery,
      bankCoverageQuery,
      listAttendanceDevices().catch(() => ({ devices: [], logs: [] })),
      notificationQuery.maybeSingle(),
    ]);

  const employeeRows = (employees ?? []) as Array<Record<string, unknown>>;
  const exportItems = (exportRows ?? []) as Array<Record<string, unknown>>;
  const payroll = payrollRun as Record<string, unknown> | null;
  const bankReady = employeeRows.filter((row) => safeString(row.bank_name) && safeString(row.bank_account)).length;

  return {
    summary: {
      connectedServices: 6,
      recentExports: exportItems.length,
      bankReadyEmployees: bankReady,
      devices: Array.isArray(devices.devices) ? devices.devices.length : 0,
    },
    connectors: [
      {
        key: "kra",
        label: "KRA",
        status: payroll ? "ready" : "awaiting payroll",
        detail: payroll ? `PAYE ${formatCurrency(safeNumber(payroll.paye_total))}` : "Run payroll to generate PAYE support schedules.",
      },
      {
        key: "shif",
        label: "SHIF",
        status: payroll ? "ready" : "awaiting payroll",
        detail: payroll ? `SHIF ${formatCurrency(safeNumber(payroll.shif_total))}` : "Payroll statutory totals not generated yet.",
      },
      {
        key: "nssf",
        label: "NSSF",
        status: payroll ? "ready" : "awaiting payroll",
        detail: payroll ? `NSSF ${formatCurrency(safeNumber(payroll.nssf_total))}` : "Payroll statutory totals not generated yet.",
      },
      {
        key: "housing_levy",
        label: "Housing Levy",
        status: payroll ? "ready" : "awaiting payroll",
        detail: payroll ? `AHL ${formatCurrency(safeNumber(payroll.housing_levy_total))}` : "Payroll statutory totals not generated yet.",
      },
      {
        key: "banks",
        label: "Banks",
        status: bankReady ? "ready" : "attention",
        detail: `${bankReady} employees have bank details ready for exports.`,
      },
      {
        key: "biometrics",
        label: "Biometric Devices",
        status: Array.isArray(devices.devices) && devices.devices.length ? "ready" : "placeholder",
        detail: Array.isArray(devices.devices) && devices.devices.length
          ? `${devices.devices.length} device connection(s) visible in Supabase.`
          : "Device APIs are staged but no device is configured yet.",
      },
      {
        key: "email",
        label: "Email Services",
        status: notificationSettings && (notificationSettings as Record<string, unknown>).email_enabled ? "ready" : "attention",
        detail: notificationSettings && (notificationSettings as Record<string, unknown>).email_enabled
          ? "Email notifications are enabled."
          : "Email notifications are currently disabled.",
      },
      {
        key: "sms",
        label: "SMS Services",
        status: "placeholder",
        detail: "SMS event hooks are planned but intentionally disabled for now.",
      },
    ],
    exports: exportItems.map((item) => ({
      id: safeString(item.id),
      exportType: safeString(item.export_type),
      status: safeString(item.status),
      fileName: safeString(item.file_name),
      createdAt: safeString(item.created_at),
      period: safeString(payroll?.period_label, "-"),
    })),
    devices,
  };
}

export async function getConsultancyWorkspace() {
  const context = await getRequestContext();
  if (!roleCanAccessModule(context.profile.role, "consultancy")) {
    throw new Error("forbidden");
  }

  const report = await getConsultancyReportsSnapshot();
  const companies = Array.isArray(report.companies) ? report.companies : [];

  return {
    summary: report.cards,
    companies,
    hotspots: companies
      .slice()
      .sort((left, right) => safeNumber(right.payrollErrors) - safeNumber(left.payrollErrors))
      .slice(0, 5),
  };
}

