function applyBuilderFilters<T extends Record<string, unknown>>(rows: T[], filters: Record<string, unknown>) {
  return rows.filter((row) => {
    return Object.entries(filters).every(([key, value]) => {
      if (value === "" || value == null) return true;
      const rowValue = row[key];
      if (Array.isArray(value)) return value.length === 0 || value.includes(rowValue);
      return String(rowValue ?? "").toLowerCase().includes(String(value).toLowerCase());
    });
  });
}

async function getBuilderDataset(context: RequestContext, moduleKey: string) {
  if (moduleKey === "employees") {
    const employees = await getScopedEmployeeDetailRows(context);
    return employees.map((row) => ({
      employee_number: safeString(row.employee_number),
      full_name: titleFromEmployee(row),
      gender: safeString(row.gender),
      date_of_birth: safeString(row.date_of_birth),
      age_years: calculateAgeYears(safeString(row.date_of_birth)),
      phone_number: safeString(row.phone),
      company_email: safeString(row.email),
      department: safeString((row.department as Record<string, unknown> | null)?.name, "-"),
      branch: safeString((row.branch as Record<string, unknown> | null)?.name, "-"),
      designation: safeString((row.designation as Record<string, unknown> | null)?.title, "-"),
      job_grade: safeString((row.job_grade as Record<string, unknown> | null)?.name, "-"),
      employment_type: safeString(row.employment_type),
      status: safeString(row.status),
      hire_date: safeString(row.hire_date),
      confirmation_date: safeString(row.confirmation_date),
      contract_end_date: safeString(row.contract_end_date),
      salary: safeNumber(row.salary),
      national_id: safeString(row.national_id),
      kra_pin: safeString(row.kra_pin),
      shif_number: safeString(row.shif_number),
      nssf_number: safeString(row.nssf_number),
      bank_name: safeString(row.bank_name),
      bank_branch: safeString(row.bank_branch),
      bank_account: safeString(row.bank_account),
      supervisor: `${safeString((row.supervisor as Record<string, unknown> | null)?.first_name)} ${safeString((row.supervisor as Record<string, unknown> | null)?.last_name)}`.trim() || "-",
    }));
  }
  if (moduleKey === "payroll") {
    const payroll = await getLatestPayrollEmployeeRows(context);
    return payroll.rows.map((row) => {
      const employee = asRecord(row.employee);
      return {
        employee_number: safeString(employee?.employee_number),
        employee_name: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        department: safeString((employee?.department as Record<string, unknown> | null)?.name, "-"),
        branch: safeString((employee?.branch as Record<string, unknown> | null)?.name, "-"),
        gross_pay: safeNumber(row.gross_pay),
        net_pay: safeNumber(row.net_pay),
        status: safeString(row.status),
      };
    });
  }
  if (moduleKey === "leave") {
    return (await listLeaveRequests()).map((row) => {
      const employee = asRecord(row.employee);
      return {
        employee_number: safeString(employee?.employee_number),
        employee_name: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        department: safeString((employee?.department as Record<string, unknown> | null)?.name, "-"),
        branch: safeString((employee?.branch as Record<string, unknown> | null)?.name, "-"),
        leave_type: safeString(row.leave_type),
        status: safeString(row.status),
        start_date: safeString(row.start_date),
        end_date: safeString(row.end_date),
        days: safeNumber(row.days),
      };
    });
  }
  if (moduleKey === "attendance") {
    return (await listAttendanceRecords()).map((row) => {
      const employee = asRecord(row.employee);
      return {
        employee_number: safeString(employee?.employee_number),
        employee_name: `${safeString(employee?.first_name)} ${safeString(employee?.last_name)}`.trim(),
        department: safeString((employee?.department as Record<string, unknown> | null)?.name, "-"),
        branch: safeString((employee?.branch as Record<string, unknown> | null)?.name, "-"),
        work_date: safeString(row.work_date),
        status: safeString(row.status),
        minutes_late: safeNumber(row.minutes_late),
        overtime_hours: safeNumber(row.overtime_hours),
      };
    });
  }
  if (moduleKey === "recruitment") {
    return (await listRecruitmentRequisitionsInternal(context)).map((row) => ({
      role_title: safeString(row.role_title),
      department: safeString((row.department as Record<string, unknown> | null)?.name, "-"),
      branch: safeString((row.branch as Record<string, unknown> | null)?.name, "-"),
      headcount: safeNumber(row.headcount),
      status: safeString(row.status),
      created_at: safeString(row.created_at),
    }));
  }
  if (moduleKey === "performance") {
    return (await listPerformanceReviewsInternal(context)).map((row) => ({
      review_cycle: safeString(row.review_cycle),
      review_period: safeString(row.review_period),
      score: safeNumber(row.score),
      status: safeString(row.status),
      promotion_recommendation: safeString(row.promotion_recommendation),
      pip_status: safeString(row.pip_status),
    }));
  }
  if (moduleKey === "training") {
    return (await listTrainingRequestsInternal(context)).map((row) => ({
      program_name: safeString(row.program_name),
      schedule: safeString(row.schedule),
      budget: safeNumber(row.budget),
      status: safeString(row.status),
    }));
  }
  if (moduleKey === "assets") {
    return (await listEmployeeAssetRowsInternal(context)).map((row) => ({
      asset_name: safeString(row.asset_name),
      asset_category: safeString(row.asset_category),
      serial_number: safeString(row.serial_number),
      status: safeString(row.status),
      issue_date: safeString(row.issue_date),
      expected_return_date: safeString(row.expected_return_date),
    }));
  }
  return [];
}

export async function getCustomReportPreview(input: {
  moduleKey: string;
  fields: string[];
  filters?: Record<string, unknown>;
}) {
  const context = await getRequestContext();
  ensureReportCategoryAccess(context.profile, "builder");
  const dataset = (await getBuilderDataset(
    context,
    input.moduleKey
  )) as Array<Record<string, unknown>>;
  const filtered = applyBuilderFilters(dataset, input.filters ?? {});
  const fields = input.fields.length ? input.fields : Object.keys(filtered[0] ?? {}).slice(0, 6);
  const preview = filtered.slice(0, 20).map((row) =>
    Object.fromEntries(fields.map((field) => [field, row[field as keyof typeof row] ?? ""]))
  );
  await logReportAccess(context, {
    moduleKey: "reports",
    category: "Custom Report Builder",
    reportName: "Custom Report Builder Preview",
    reportKey: `builder_${input.moduleKey}`,
    action: "preview",
    filters: input.filters ?? {},
  });
  return { fields, preview, totalRows: filtered.length };
}

