async function buildReportRowsByKey(context: RequestContext, reportKey: string, filters: Record<string, unknown>) {
  if (reportKey.startsWith("builder_")) {
    const moduleKey = reportKey.replace(/^builder_/, "");
    return (await getBuilderDataset(context, moduleKey)) as Array<Record<string, unknown>>;
  }
  if (reportKey === "executive_dashboard") {
    const report = await getExecutiveDashboardReport();
    return [
      {
        total_employees: safeNumber(report.metrics.totalEmployees),
        active_employees: safeNumber(report.metrics.activeEmployees),
        payroll_cost: safeString(report.metrics.totalMonthlyPayrollCost),
        net_pay: safeString(report.metrics.totalNetPay),
        attendance_rate: safeNumber(report.metrics.attendanceRate),
        turnover_rate: safeNumber(report.metrics.turnoverRate),
      },
    ];
  }
  if (reportKey === "employee_master_list") {
    return (await getBuilderDataset(context, "employees")) as Array<Record<string, unknown>>;
  }
  if (reportKey === "payroll_register") {
    return (await getBuilderDataset(context, "payroll")) as Array<Record<string, unknown>>;
  }
  if (reportKey === "leave_summary") {
    return (await getBuilderDataset(context, "leave")) as Array<Record<string, unknown>>;
  }
  if (reportKey === "attendance_summary") {
    return (await getBuilderDataset(context, "attendance")) as Array<Record<string, unknown>>;
  }
  if (reportKey === "recruitment_pipeline") {
    return (await getBuilderDataset(context, "recruitment")) as Array<Record<string, unknown>>;
  }
  if (reportKey === "performance_distribution") {
    return (await getBuilderDataset(context, "performance")) as Array<Record<string, unknown>>;
  }
  if (reportKey === "training_requests") {
    return (await getBuilderDataset(context, "training")) as Array<Record<string, unknown>>;
  }
  if (reportKey === "asset_allocation") {
    return (await getBuilderDataset(context, "assets")) as Array<Record<string, unknown>>;
  }
  if (reportKey === "compliance_gaps") {
    return ((await getComplianceReportsSnapshot()).gaps ?? []) as Array<Record<string, unknown>>;
  }
  if (reportKey === "branch_reports") {
    return (await getBranchReportsSnapshot()) as Array<Record<string, unknown>>;
  }
  if (reportKey === "department_reports") {
    return (await getDepartmentReportsSnapshot()) as Array<Record<string, unknown>>;
  }
  if (reportKey === "consultancy_reports") {
    return (((await getConsultancyReportsSnapshot()).companies ?? []) as Array<Record<string, unknown>>);
  }

  return applyBuilderFilters((await getBuilderDataset(context, "employees")) as Array<Record<string, unknown>>, filters);
}

export async function getReportExportDownload(exportId: string) {
  const context = await getRequestContext();
  ensureReportCategoryAccess(context.profile, "exports");
  const { data, error } = await context.supabase
    .from("report_exports")
    .select("*")
    .eq("id", exportId)
    .maybeSingle();
  if (error || !data) throw error ?? new Error("report_export_not_found");
  const rawFilters = ((data.filters as Record<string, unknown>) ?? {}) as Record<string, unknown>;
  const selectedFields = Array.isArray(rawFilters.fields)
    ? rawFilters.fields.filter((value): value is string => typeof value === "string" && value.length > 0)
    : [];
  const filterInput = Object.fromEntries(Object.entries(rawFilters).filter(([key]) => key !== "fields"));
  const rows = await buildReportRowsByKey(context, safeString(data.report_key), filterInput);
  const filtered = applyBuilderFilters(rows, filterInput);
  const headers = selectedFields.length ? selectedFields : Object.keys(filtered[0] ?? {});
  const safeHeaders = headers.length ? headers : ["message"];
  if (safeString(data.export_type) === "pdf") {
    const branding = await getCompanyBrandingContext(
      context.profile.company_id,
      "Solva HR Workspace",
      safeString(context.profile.company_id)
    );
    const columns: GenericReportPdfColumn[] = safeHeaders.map((header) => {
      const sampleValue = filtered.find((row) => row[header] != null)?.[header];
      const looksNumeric =
        typeof sampleValue === "number" ||
        (typeof sampleValue === "string" && /^-?\d[\d,]*(\.\d+)?$/.test(sampleValue.trim()));
      return {
        key: header,
        label: toTitle(header),
        widthRatio: looksNumeric ? 0.8 : header.includes("detail") || header.includes("name") ? 1.5 : 1,
        align: looksNumeric ? "right" : "left",
      };
    });
    const pdf = buildGenericTabularReportPdf({
      organizationName: branding.organizationName,
      organizationIdentifier: branding.organizationIdentifier,
      organizationLogoMark: branding.organizationLogoMark,
      organizationLogoJpeg: branding.organizationLogoJpeg,
      platformLogoJpeg: branding.platformLogoJpeg,
      organizationAddressLines: branding.organizationAddressLines,
      title: safeString(data.report_name, "Report Export"),
      periodLine: safeString(filterInput.period, "Live production snapshot"),
      generatedAtLabel: formatGeneratedTimestamp(new Date().toISOString()),
      generatedBy: safeString(context.profile.full_name, context.profile.email),
      reportFooter: branding.reportFooter,
      columns,
      rows: (filtered.length ? filtered : [{ message: "No rows available for the selected filters." }]).map((row) =>
        Object.fromEntries(
          safeHeaders.map((header) => [
            header,
            typeof row[header] === "number" ? Number(row[header]).toLocaleString("en-KE") : row[header] ?? "",
          ])
        )
      ),
    });
    return {
      fileName: safeString(data.file_name, "report.pdf"),
      contentType: "application/pdf",
      content: Buffer.from(pdf),
    };
  }
  const csv = [
    safeHeaders.join(","),
    ...filtered.map((row) => safeHeaders.map((header) => `"${String(row[header] ?? "").replace(/"/g, '""')}"`).join(",")),
  ].join("\n");
  return {
    fileName: safeString(data.file_name, "report.csv"),
    contentType: safeString(data.export_type) === "excel" ? "application/vnd.ms-excel" : "text/csv; charset=utf-8",
    content: csv,
  };
}

