export async function createEssComplaint(input: {
  category: string;
  subject?: string;
  details: string;
}) {
  const context = await getRequestContext();

  if (!context.profile.employee_id) {
    throw new Error("employee_profile_required");
  }

  const { data: employee, error } = await context.supabase
    .from("employees")
    .select("id, employee_number, first_name, last_name, supervisor_employee_id, department:department_id(name), branch:branch_id(name)")
    .eq("id", context.profile.employee_id)
    .single();

  if (error || !employee) {
    throw error ?? new Error("employee_not_found");
  }

  const supervisorEmployeeId = safeString(employee.supervisor_employee_id);
  if (!supervisorEmployeeId) {
    throw new Error("supervisor_not_assigned");
  }

  const employeeName = `${safeString(employee.first_name)} ${safeString(employee.last_name)}`.trim();
  const departmentName = safeString(asRecord(employee.department)?.name, "Unassigned");
  const branchName = safeString(asRecord(employee.branch)?.name, "Unassigned");
  const task = await createTask(context, {
    module_key: "ess",
    entity_type: "staff_complaint",
    entity_id: safeString(employee.id),
    title: input.subject?.trim() ? input.subject.trim() : `Complaint: ${input.category}`,
    description: input.details,
    owner_role: "Supervisor",
    stage: "Supervisor review",
    metadata: {
      category: input.category,
      requestType: "Staff Complaint",
      employeeId: safeString(employee.id),
      employeeNumber: safeString(employee.employee_number),
      employeeName,
      departmentName,
      branchName,
      requestedByName: employeeName,
      assignedSupervisorEmployeeId: supervisorEmployeeId,
      response: "",
      privateNotes: "",
      visibility: "supervisor_only",
      allowed_approver_roles: ["Supervisor", "Manager", "HR Admin", "Payroll Admin", "Super Admin"],
    },
  });

  return {
    id: safeString(task.id),
    title: safeString(task.title),
    category: input.category,
    status: safeString(task.status),
    stage: safeString(task.stage),
    details: input.details,
    response: "",
    privateNotes: "",
    updatedAt: safeString(task.updated_at, safeString(task.created_at)),
  };
}

export async function listEssComplaints() {
  const context = await getRequestContext();

  let query = context.supabase
    .from("approval_tasks")
    .select("id, title, description, status, stage, updated_at, created_at, metadata, requested_by, owner_role")
    .eq("module_key", "ess")
    .eq("entity_type", "staff_complaint")
    .order("updated_at", { ascending: false })
    .limit(100);

  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }

  if (context.profile.role === "Employee") {
    query = query.eq("requested_by", context.profile.id);
  }

  const { data, error } = await query;
  if (error) {
    throw error;
  }

  const rows = (data ?? []) as TaskRow[];

  if (context.profile.role === "Supervisor" && context.profile.employee_id) {
    const scopedEmployeeIds = new Set((await getScopedEmployeeIds(context)) ?? []);
    return rows
      .filter((row) => {
        const metadata = asRecord(row.metadata);
        return scopedEmployeeIds.has(safeString(metadata?.employeeId));
      })
      .map((row) => {
        const metadata = asRecord(row.metadata);
        return {
          id: safeString(row.id),
          title: safeString(row.title),
          category: safeString(metadata?.category),
          status: safeString(row.status),
          stage: safeString(row.stage),
          details: safeString(row.description),
          response: safeString(metadata?.response),
          privateNotes: safeString(metadata?.privateNotes),
          employeeName: safeString(metadata?.employeeName),
          employeeNumber: safeString(metadata?.employeeNumber),
          createdAt: safeString(row.created_at),
          updatedAt: safeString(row.updated_at, safeString(row.created_at)),
        };
      });
  }

  const filtered = context.profile.role === "Employee" ? rows : [];

  return filtered.map((row) => {
    const metadata = asRecord(row.metadata);
    return {
      id: safeString(row.id),
      title: safeString(row.title),
      category: safeString(metadata?.category),
      status: safeString(row.status),
      stage: safeString(row.stage),
      details: safeString(row.description),
      response: safeString(metadata?.response),
      privateNotes:
        context.profile.role === "Supervisor" ? safeString(metadata?.privateNotes) : "",
      employeeName: safeString(metadata?.employeeName),
      employeeNumber: safeString(metadata?.employeeNumber),
      createdAt: safeString(row.created_at),
      updatedAt: safeString(row.updated_at, safeString(row.created_at)),
    };
  });
}

export async function updateEssComplaint(
  complaintId: string,
  input: {
    status?: "pending" | "in_review" | "resolved";
    response?: string;
    privateNotes?: string;
  }
) {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Supervisor", "Manager", "HR Admin", "Super Admin"]);

  const { data: task, error } = await context.supabase
    .from("approval_tasks")
    .select("*")
    .eq("id", complaintId)
    .eq("entity_type", "staff_complaint")
    .maybeSingle();

  if (error || !task) {
    throw error ?? new Error("complaint_not_found");
  }

  const metadata = asRecord(task.metadata) ?? {};
  if (context.profile.role !== "Super Admin") {
    const scopedEmployeeIds = new Set((await getScopedEmployeeIds(context)) ?? []);
    if (!scopedEmployeeIds.has(safeString(metadata.employeeId))) {
      throw new Error("forbidden");
    }
  }

  const nextStatus = input.status ?? safeString(task.status, "pending");
  const nextStage =
    nextStatus === "resolved"
      ? "Resolved by supervisor"
      : nextStatus === "in_review"
        ? "Supervisor review in progress"
        : "Supervisor review";
  const nextMetadata = {
    ...metadata,
    response: input.response ?? safeString(metadata.response),
    privateNotes: input.privateNotes ?? safeString(metadata.privateNotes),
    respondedAt: new Date().toISOString(),
    respondedBy: context.profile.email,
  };

  const { data: updated, error: updateError } = await context.supabase
    .from("approval_tasks")
    .update({
      status: nextStatus,
      stage: nextStage,
      metadata: nextMetadata,
      updated_at: new Date().toISOString(),
    })
    .eq("id", complaintId)
    .select("*")
    .single();

  if (updateError || !updated) {
    throw updateError ?? new Error("complaint_update_failed");
  }

  await createAuditLog(context, {
    moduleKey: "ess",
    entityType: "staff_complaint",
    entityId: complaintId,
    action: "updated_complaint",
    beforeValue: task as Record<string, unknown>,
    afterValue: updated as Record<string, unknown>,
  });

  return updated;
}

export async function createSalaryChangeRequest(input: {
  employeeId: string;
  proposedSalary: number;
  effectiveDate: string;
  reason: string;
  supportingComments?: string;
}) {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Supervisor", "Manager", "HR Admin", "Super Admin"]);
  await assertEmployeeScope(context, input.employeeId);

  const { data: employee, error } = await context.supabase
    .from("employees")
    .select("id, employee_number, first_name, last_name, salary")
    .eq("id", input.employeeId)
    .single();

  if (error || !employee) {
    throw error ?? new Error("employee_not_found");
  }

  const currentSalary = roundPayrollAmount(safeNumber(employee.salary));
  const employeeName = `${safeString(employee.first_name)} ${safeString(employee.last_name)}`.trim();

  if (canDirectSalaryReview(context.profile.role)) {
    return applySalaryChangeDirect(context, {
      employeeId: input.employeeId,
      currentSalary,
      proposedSalary: input.proposedSalary,
      effectiveDate: input.effectiveDate,
      reason: input.reason,
      supportingComments: input.supportingComments,
    });
  }

  const task = await createTask(context, {
    module_key: "performance",
    entity_type: "salary_change_request",
    entity_id: input.employeeId,
    title: `Salary change request for ${employeeName}`,
    description: input.reason,
    owner_role: "Manager",
    stage: "General Manager review",
    metadata: {
      requestType: "Salary Review",
      employeeId: input.employeeId,
      employeeName,
      employeeNumber: safeString(employee.employee_number),
      currentSalary,
      proposedSalary: roundPayrollAmount(input.proposedSalary),
      effectiveDate: input.effectiveDate,
      reason: input.reason,
      supportingComments: input.supportingComments ?? "",
      requestedBySupervisorEmployeeId: safeString(context.profile.employee_id),
      requestedByRole: context.profile.role,
      priority: "High",
      allowed_approver_roles: ["Manager", "HR Admin", "Payroll Admin", "Finance Officer", "Super Admin"],
      final_status: "approved",
    },
  });

  return mapApprovalTask(task as TaskRow);
}

export async function listSalaryChangeRequests() {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Supervisor", "Manager", "Payroll Admin", "HR Admin", "Super Admin"]);

  let query = context.supabase
    .from("approval_tasks")
    .select("id, title, description, owner_role, status, stage, updated_at, created_at, metadata, requested_by")
    .eq("entity_type", "salary_change_request")
    .order("updated_at", { ascending: false })
    .limit(100);

  if (context.profile.company_id) {
    query = query.eq("company_id", context.profile.company_id);
  }

  const { data, error } = await query;
  if (error) {
    throw error;
  }

  const rows = (data ?? []) as TaskRow[];
  const filtered = rows.filter((row) => {
    const metadata = asRecord(row.metadata);

    if (context.profile.role === "Supervisor") {
      return (
        safeString(metadata?.requestedBySupervisorEmployeeId) === safeString(context.profile.employee_id)
      );
    }

    if (context.profile.role === "Manager") {
      if (isRobotCafeCompany(context.profile.company_id)) {
        return true;
      }
      const allowed = Array.isArray(metadata?.allowed_approver_roles)
        ? metadata.allowed_approver_roles.map((value) => safeString(value))
        : [];
      return allowed.includes("Manager") || safeString(row.owner_role) === "Manager";
    }

    return true;
  });

  return filtered.map((row) => {
    const metadata = asRecord(row.metadata);
    return {
      id: safeString(row.id),
      title: safeString(row.title),
      status: safeString(row.status),
      stage: safeString(row.stage),
      ownerRole: safeString(row.owner_role),
      employeeName: safeString(metadata?.employeeName),
      employeeNumber: safeString(metadata?.employeeNumber),
      currentSalary: formatCurrency(safeNumber(metadata?.currentSalary)),
      proposedSalary: formatCurrency(safeNumber(metadata?.proposedSalary)),
      effectiveDate: safeString(metadata?.effectiveDate),
      reason: safeString(metadata?.reason, safeString(row.description)),
      supportingComments: safeString(metadata?.supportingComments),
      updatedAt: safeString(row.updated_at, safeString(row.created_at)),
    };
  });
}

