export async function listCompanyReferrals() {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Manager", "HR Admin", "Payroll Admin", "Super Admin"]);

  const admin = createSupabaseAdminClient();
  const { data, error } = await admin
    .from("company_referrals")
    .select("*")
    .eq("company_id", context.profile.company_id)
    .order("created_at", { ascending: false })
    .limit(50);

  if (error) {
    throw error;
  }

  const rows = ((data ?? []) as Array<Record<string, unknown>>).map((row) => ({
    id: safeString(row.id),
    companyName: safeString(row.referred_company_name),
    contactPerson: safeString(row.contact_person),
    contactEmail: safeString(row.contact_email),
    contactPhone: safeString(row.contact_phone),
    industry: safeString(row.industry),
    notes: safeString(row.notes),
    rewardType: safeString(row.reward_type),
    rewardValue: safeString(row.reward_value),
    status: safeString(row.status, "new"),
    createdByRole: safeString(row.created_by_role),
    createdAt: safeString(row.created_at),
    updatedAt: safeString(row.updated_at, safeString(row.created_at)),
  }));

  const statusCounts = rows.reduce<Record<string, number>>((summary, row) => {
    const key = row.status || "new";
    summary[key] = (summary[key] ?? 0) + 1;
    return summary;
  }, {});

  return {
    metrics: {
      totalReferrals: rows.length,
      newReferrals: statusCounts.new ?? 0,
      contactedReferrals: statusCounts.contacted ?? 0,
      convertedReferrals: statusCounts.converted ?? 0,
      rewardedReferrals: rows.filter((row) => row.rewardType.length > 0).length,
    },
    referrals: rows,
  };
}

export async function createCompanyReferral(input: {
  companyName: string;
  contactPerson: string;
  contactEmail?: string;
  contactPhone?: string;
  industry?: string;
  notes?: string;
  rewardType?: string;
  rewardValue?: string;
}) {
  const context = await getRequestContext();
  ensureRole(context.profile, ["Manager", "HR Admin", "Payroll Admin", "Super Admin"]);

  const companyName = safeString(input.companyName).trim();
  const contactPerson = safeString(input.contactPerson).trim();
  if (!companyName || !contactPerson) {
    throw new Error("missing_referral_fields");
  }

  const admin = createSupabaseAdminClient();
  const leadNotes = [
    safeString(input.notes),
    safeString(input.rewardType) ? `Preferred referral reward: ${safeString(input.rewardType)}` : "",
    safeString(input.rewardValue) ? `Reward detail: ${safeString(input.rewardValue)}` : "",
    `Referred internally by ${safeString(context.profile.full_name, context.profile.email)} (${context.profile.role}).`,
  ]
    .filter(Boolean)
    .join(" ");

  const { data: leadRow, error: leadError } = await admin
    .from("sales_leads")
    .insert({
      source: "tenant_referral",
      lead_type: "contact_sales",
      company_name: companyName,
      contact_person: contactPerson,
      email: safeString(input.contactEmail).toLowerCase() || null,
      phone: safeString(input.contactPhone) || null,
      country: "Kenya",
      notes: leadNotes || null,
      modules: ["people", "payroll", "ess", "reports"],
      status: "new",
    })
    .select("id")
    .maybeSingle();

  if (leadError) {
    throw leadError;
  }

  const rewardType = safeString(input.rewardType, "free_month");
  const rewardValue = safeString(input.rewardValue);
  const { data, error } = await admin
    .from("company_referrals")
    .insert({
      company_id: context.profile.company_id,
      referred_company_name: companyName,
      contact_person: contactPerson,
      contact_email: safeString(input.contactEmail) || null,
      contact_phone: safeString(input.contactPhone) || null,
      industry: safeString(input.industry) || null,
      notes: safeString(input.notes) || null,
      reward_type: rewardType,
      reward_value: rewardValue || null,
      status: "new",
      source: "internal_referral",
      created_by_user_id: context.profile.id,
      created_by_role: context.profile.role,
      converted_lead_id: safeString(leadRow?.id) || null,
    })
    .select("*")
    .single();

  if (error || !data) {
    throw error ?? new Error("referral_create_failed");
  }

  await createAuditLog(context, {
    moduleKey: "dashboard",
    entityType: "company_referral",
    entityId: safeString(data.id),
    action: "created_company_referral",
    afterValue: data as Record<string, unknown>,
  });

  return {
    id: safeString(data.id),
    companyName,
    contactPerson,
    rewardType,
    rewardValue,
    status: safeString((data as Record<string, unknown>).status, "new"),
  };
}

export async function listEmployeeActionMessages(
  employeeId: string,
  entityType: string,
  entityId: string
) {
  const context = await getRequestContext();
  await assertEmployeeScope(context, employeeId);

  const { data, error } = await context.supabase
    .from("employee_action_messages")
    .select("*")
    .eq("employee_id", employeeId)
    .eq("entity_type", entityType)
    .eq("entity_id", entityId)
    .order("created_at", { ascending: true })
    .limit(100);

  if (error) {
    throw error;
  }

  return ((data ?? []) as Array<Record<string, unknown>>).map((row) => ({
    id: safeString(row.id),
    title: safeString(row.title),
    entityType: safeString(row.entity_type),
    entityId: safeString(row.entity_id),
    authorRole: safeString(row.author_role),
    authorName: safeString(row.author_name),
    message: safeString(row.message),
    createdAt: safeString(row.created_at),
  }));
}

export async function listEmployeeActionThreads(employeeId: string) {
  const context = await getRequestContext();
  await assertEmployeeScope(context, employeeId);

  const { data, error } = await context.supabase
    .from("employee_action_messages")
    .select("*")
    .eq("employee_id", employeeId)
    .order("created_at", { ascending: false })
    .limit(200);

  if (error) {
    throw error;
  }

  const grouped = new Map<
    string,
    {
      id: string;
      title: string;
      entityType: string;
      entityId: string;
      latestMessage: string;
      latestAuthor: string;
      updatedAt: string;
      messageCount: number;
    }
  >();

  for (const row of (data ?? []) as Array<Record<string, unknown>>) {
    const entityType = safeString(row.entity_type);
    const entityId = safeString(row.entity_id);
    const key = `${entityType}:${entityId}`;
    const existing = grouped.get(key);
    if (existing) {
      existing.messageCount += 1;
      continue;
    }
    grouped.set(key, {
      id: safeString(row.id),
      title: safeString(row.title, toTitle(entityType.replace(/_/g, " "))),
      entityType,
      entityId,
      latestMessage: safeString(row.message),
      latestAuthor: safeString(row.author_name, safeString(row.author_role)),
      updatedAt: safeString(row.created_at),
      messageCount: 1,
    });
  }

  return Array.from(grouped.values());
}

export async function postEmployeeActionMessage(
  employeeId: string,
  entityType: string,
  entityId: string,
  message: string
) {
  const context = await getRequestContext();
  await assertEmployeeScope(context, employeeId);
  const trimmed = safeString(message).trim();

  if (!trimmed) {
    throw new Error("message_required");
  }

  const admin = createSupabaseAdminClient();
  const { data, error } = await admin
    .from("employee_action_messages")
    .insert({
      company_id: context.profile.company_id,
      employee_id: employeeId,
      entity_type: entityType,
      entity_id: entityId,
      author_user_id: context.profile.id,
      author_role: context.profile.role,
      author_name: safeString(context.profile.full_name, context.profile.email),
      message: trimmed,
    })
    .select("*")
    .single();

  if (error || !data) {
    throw error ?? new Error("message_create_failed");
  }

  const recipientIds = await resolveEmployeeRecipientIds(context.profile.company_id, employeeId);
  const notifyApproverRoles =
    context.profile.role === "Employee"
      ? ["HR Admin", "Payroll Admin", "Supervisor", "Manager", "Super Admin"]
      : ["Employee"];

  const userRecipients =
    context.profile.role === "Employee"
      ? await admin
          .from("users")
          .select("id")
          .eq("company_id", safeString(context.profile.company_id))
          .in("role", notifyApproverRoles)
      : await admin
          .from("users")
          .select("id")
          .eq("company_id", safeString(context.profile.company_id))
          .eq("employee_id", employeeId);

  const recipientPool =
    context.profile.role === "Employee"
      ? ((userRecipients.data ?? []) as Array<Record<string, unknown>>).map((row) => safeString(row.id))
      : recipientIds;

  if (recipientPool.length) {
    await admin.from("notifications").insert(
      recipientPool
        .filter((userId) => userId && userId !== context.profile.id)
        .map((userId) => ({
          company_id: context.profile.company_id,
          user_id: userId,
          title: context.profile.role === "Employee" ? "Staff reply received" : "Approver reply received",
          message: trimmed,
          category: "staff_actions",
          link_href: context.profile.role === "Employee"
            ? `/?module=dashboard&item=Pending%20Approvals`
            : `/?module=ess&item=My%20Notifications&entityType=${encodeURIComponent(entityType)}&entityId=${encodeURIComponent(entityId)}`,
          status: "unread",
        }))
    );
  }

  await createAuditLog(context, {
    moduleKey: context.profile.role === "Employee" ? "ess" : "people",
    entityType: "employee_action_message",
    entityId: safeString(data.id),
    action: "posted_employee_action_message",
    afterValue: data as Record<string, unknown>,
  });

  return {
    id: safeString(data.id),
    title: safeString((data as Record<string, unknown>).title),
    entityType: safeString((data as Record<string, unknown>).entity_type),
    entityId: safeString((data as Record<string, unknown>).entity_id),
    authorRole: safeString((data as Record<string, unknown>).author_role),
    authorName: safeString((data as Record<string, unknown>).author_name),
    message: safeString((data as Record<string, unknown>).message),
    createdAt: safeString((data as Record<string, unknown>).created_at),
  };
}

