export async function getEssSettings() {
  const context = await getRequestContext();
  const { data, error } = await context.supabase
    .from("ess_preferences")
    .select("*")
    .eq("user_id", context.profile.id)
    .maybeSingle();

  if (error) {
    throw error;
  }

  const preference = data ?? {
    theme_mode: "light",
    email_notifications: true,
    sms_notifications: false,
    in_app_notifications: true,
    language: "en",
  };

  return {
    themeMode: safeString(preference.theme_mode, "light"),
    emailNotifications: Boolean(preference.email_notifications ?? true),
    smsNotifications: Boolean(preference.sms_notifications ?? false),
    inAppNotifications: Boolean(preference.in_app_notifications ?? true),
    language: safeString(preference.language, "en"),
  };
}

export async function updateEssSettings(input: {
  themeMode?: string;
  emailNotifications?: boolean;
  smsNotifications?: boolean;
  inAppNotifications?: boolean;
  language?: string;
}) {
  const context = await getRequestContext();
  const before = await getEssSettings();

  const payload = {
    user_id: context.profile.id,
    ...(typeof input.themeMode !== "undefined" ? { theme_mode: input.themeMode } : {}),
    ...(typeof input.emailNotifications !== "undefined" ? { email_notifications: input.emailNotifications } : {}),
    ...(typeof input.smsNotifications !== "undefined" ? { sms_notifications: input.smsNotifications } : {}),
    ...(typeof input.inAppNotifications !== "undefined" ? { in_app_notifications: input.inAppNotifications } : {}),
    ...(typeof input.language !== "undefined" ? { language: input.language } : {}),
  };

  const { error } = await context.supabase.from("ess_preferences").upsert(payload, { onConflict: "user_id" });

  if (error) {
    throw error;
  }

  await createAuditLog(context, {
    moduleKey: "ess",
    entityType: "ess_preferences",
    entityId: context.profile.id,
    action: "updated_ess_settings",
    beforeValue: before as unknown as Record<string, unknown>,
    afterValue: payload as Record<string, unknown>,
  });

  return getEssSettings();
}

export async function changeEssPassword(input: {
  currentPassword: string;
  newPassword: string;
  confirmPassword: string;
}) {
  const context = await getRequestContext();
  if (!context.profile.email) {
    throw new Error("unauthorized");
  }

  const currentPassword = safeString(input.currentPassword);
  const newPassword = safeString(input.newPassword);
  const confirmPassword = safeString(input.confirmPassword);

  if (!currentPassword || !newPassword || !confirmPassword) {
    throw new Error("password_fields_required");
  }

  if (newPassword !== confirmPassword) {
    throw new Error("password_confirmation_mismatch");
  }

  if (newPassword.length < 8) {
    throw new Error("password_too_short");
  }

  const verifier = await createSupabaseServerClient();
  const verifyResult = await verifier.auth.signInWithPassword({
    email: safeString(context.profile.email),
    password: currentPassword,
  });

  if (verifyResult.error) {
    throw new Error("current_password_incorrect");
  }

  const updateResult = await verifier.auth.updateUser({
    password: newPassword,
  });

  if (updateResult.error) {
    throw updateResult.error;
  }

  await context.supabase
    .from("users")
    .update({
      must_reset_password: false,
      updated_at: new Date().toISOString(),
    })
    .eq("id", context.profile.id);

  await createAuditLog(context, {
    moduleKey: "ess",
    entityType: "user_password",
    entityId: safeString(context.profile.id),
    action: "changed_password_from_ess",
    afterValue: {
      changedAt: new Date().toISOString(),
      changedBy: safeString(context.profile.email),
    },
  });

  return { success: true };
}

export async function markEssNotificationRead(notificationId?: string | null) {
  const context = await getRequestContext();
  let query = context.supabase.from("notifications").update({ status: "read" }).eq("user_id", context.profile.id);

  if (notificationId) {
    query = query.eq("id", notificationId);
  } else {
    query = query.eq("status", "unread");
  }

  const { error } = await query;
  if (error) {
    throw error;
  }

  await createAuditLog(context, {
    moduleKey: "ess",
    entityType: "notification",
    entityId: notificationId ?? context.profile.id,
    action: notificationId ? "marked_notification_read" : "marked_all_notifications_read",
  });

  return { success: true };
}

